/* Controle Financeiro Mobile v0.7 — páginas e ações de paridade total */

function sectionHead(title,action=''){return `<div class="page-head"><div><div class="page-title">${escapeHtml(title)}</div><div class="page-subtitle">Mesmas regras e dados do Controle Financeiro no PC</div></div>${action}</div>`}
function searchValue(key){return state.meta.uiSearch?.[key]||''}
function setSearchValue(key,v){state.meta.uiSearch[key]=v;save()}
function matchSearch(obj,q){q=String(q||'').trim().toLocaleLowerCase('pt-BR');if(!q)return true;return Object.values(obj||{}).join(' ').toLocaleLowerCase('pt-BR').includes(q)}
function appCardTitle(title,sub=''){return `<div class="row-between"><div><div class="section-title">${escapeHtml(title)}</div>${sub?`<div class="muted small">${escapeHtml(sub)}</div>`:''}</div></div>`}
function backButton(route){return `<button class="secondary compact" onclick="nav('${route}')">‹ Voltar</button>`}

// ---------------- DASHBOARD ----------------
function home(){
  const f=getFilters('dashboard'),y=Number(f.year)||latestPeriod().year,m=Number(f.month)||latestPeriod().month,d=periodMetrics(y,m),ds=debtSummary(),nw=networthSummary(),series=monthlySeries(y),cats=Object.entries(d.categories),budget=budgetRows(y,m).reduce((s,x)=>s+x.budget,0),used=budget?d.expense/budget*100:0;
  return `<section>
    <div class="hero-greeting">Olá, ${escapeHtml(String(data.settings.userName||'Usuário').split(' ')[0])} 👋</div>
    <div class="date-line">${todayBR()} • período ${monthName(m)}/${y}</div>
    ${filterBar('dashboard')}
    <div class="card sync-card" onclick="nav('sync')"><div class="drive-icon">▲</div><div style="flex:1"><div class="row-between"><div><div class="sync-title">${state.meta.syncConnected?'Google Drive sincronizado':'Google Drive não conectado'}</div><div class="sync-sub"><span class="dot"></span>${state.meta.syncConnected?`Revisão ${state.meta.driveLastRevision||0} • automático ${state.meta.autoSyncEnabled!==false?'ativo':'desligado'}`:'Toque para configurar a sincronização'}</div></div><span class="chip ${state.meta.pendingChanges?'yellow':'green'}">${state.meta.pendingChanges||0} pend.</span></div></div></div>
    <div class="kpi-grid-3">
      ${kpiHtml('Receitas',fmt(d.income),`${d.transactions} movimentações`,'green')}
      ${kpiHtml('Gastos',fmt(d.expense),`Essenciais ${fmt(d.essential)}`,'red')}
      ${kpiHtml('Saldo',fmt(d.balance),`Poupança ${pct(d.savings_rate)}`,'')}
      ${kpiHtml('Aportes',fmt(d.investments),`${pct(d.investment_rate)} da renda`,'purple')}
      ${kpiHtml('Dívidas',fmt(ds.balance),`Parcelas/mês ${fmt(ds.monthly)}`,'red')}
      ${kpiHtml('Patrimônio líquido',fmt(nw.networth),'Contas + investimentos − dívidas','green')}
    </div>
    <div class="card"><div class="row-between"><div class="section-title">Ações rápidas</div><button class="link-btn" onclick="openDashboardComposition()">Composição</button></div><div class="quick-actions"><button class="quick" onclick="openNewTransaction()"><div class="qicon">⇄</div><small>Novo lançamento</small></button><button class="quick" onclick="nav('goals')"><div class="qicon">◎</div><small>Metas</small></button><button class="quick" onclick="nav('networth')"><div class="qicon">◆</div><small>Conciliar</small></button><button class="quick" onclick="nav('investments')"><div class="qicon">▥</div><small>Investimentos</small></button></div></div>
    <div class="card">${appCardTitle('Fluxo mensal',`Receitas e gastos de ${y}`)}${monthlyBars(series)}</div>
    <div class="card">${appCardTitle('Gastos por categoria',`${monthName(m)}/${y}`)}${simpleBars(cats,9)}</div>
    <div class="card"><div class="row-between"><div><div class="section-title">Orçamento do período</div><div class="muted small">${fmt(d.expense)} de ${fmt(budget)} planejados</div></div><strong>${budget?pct(used):'—'}</strong></div><div class="progress ${used>=90?'yellow':'blue'}" style="margin-top:9px"><div style="width:${Math.min(100,used)}%"></div></div></div>
    <div class="card">${appCardTitle('Leitura do período')}${infoRows([['Saldo',fmt(d.balance)],['Gastos discricionários',fmt(d.discretionary)],['Resgates de investimento',fmt(d.withdrawals)],['Histórico agregado utilizado',d.historical_used?'Sim':'Não']])}</div>
    <div class="card"><div class="row-between"><div class="section-title">Saúde financeira</div><button class="link-btn" onclick="nav('health')">Ver detalhes</button></div>${healthCard()}</div>
  </section>`;
}
function openDashboardComposition(){const f=getFilters('dashboard'),comp=dashboardComposition(Number(f.year),Number(f.month)),blocks=Object.entries(comp).map(([title,items])=>{const total=items.reduce((s,x)=>s+Number(x[1]||0),0);return `<div class="card soft-card"><div class="section-title">${escapeHtml(title)}</div>${items.slice(0,30).map(([n,v])=>`<div class="info-row"><span>${escapeHtml(n)}</span><strong class="${Number(v)>=0?'income':'expense'}">${fmt(v)}</strong></div>`).join('')}<div class="info-row total-row"><span>Total</span><strong>${fmt(total)}</strong></div></div>`}).join('');openModal(`<div class="sheet-handle"></div><div class="sheet-title">Composição dos indicadores</div><div class="sheet-sub">Mostra de onde vem cada número da Visão Geral.</div>${blocks}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function healthCard(){const h=financialHealth();return `<div class="row-between"><div><div style="font-size:34px;font-weight:900;color:${h.score>=75?'var(--green)':h.score>=50?'var(--yellow)':'var(--red)'}">${Math.round(h.score)}/100</div><div class="muted small">Leitura combinada dos indicadores</div></div><span class="chip ${h.score>=75?'green':h.score>=50?'yellow':'blue'}">Reserva ${h.reserve_months.toFixed(1).replace('.',',')} meses</span></div>`}

// ---------------- MOVIMENTAÇÕES ----------------
function filteredTransactions(){const f=getFilters('transactions'),q=searchValue('transactions');return (data.transactions||[]).filter(x=>{if(!inPeriod(x,f.year,Number(f.month)))return false;if(f.type!=='all'&&x.type!==f.type)return false;if(f.category!=='Todas'&&x.category!==f.category)return false;if(f.account!=='Todas'&&x.account!==f.account)return false;if(f.impact!=='Todos'&&(boolish(x.impactBudget,true)!==(f.impact==='Sim')))return false;if(f.own!=='Todos'&&(boolish(x.ownTransfer,false)!==(f.own==='Sim')))return false;return matchSearch(x,q)}).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.id).localeCompare(String(a.id)))}
function groupedTransactions(list){const groups={};list.forEach(x=>(groups[x.date]??=[]).push(x));return Object.keys(groups).sort().reverse().map(date=>`<div class="tx-group-title">${date===isoToday()?'Hoje':brDate(date)}</div><div class="card">${groups[date].map(tx=>`<div class="tx" onclick="openTxActions('${tx.id}')"><div class="tx-icon">${tx.icon||'•'}</div><div><div class="tx-title">${escapeHtml(tx.description)}</div><div class="tx-sub">${escapeHtml(tx.category)} • ${escapeHtml(tx.account||'Conta')}${boolish(tx.ownTransfer)?' • transferência própria':''}${!boolish(tx.impactBudget,true)?' • fora do orçamento':''}</div></div><div><div class="tx-amount ${tx.type==='income'?'income':'expense'}">${tx.type==='income'?'+ ':'- '}${fmt(tx.amount)}</div><div class="tx-time">${tx.time||''}</div></div></div>`).join('')}</div>`).join('')}
function transactions(){const rows=filteredTransactions();return `${sectionHead('Movimentações','<button class="secondary" onclick="nav(\'import\')">Importar Nubank</button>')}${filterBar('transactions')}<div class="search-row"><input id="txSearch" class="search" placeholder="Buscar descrição, identificador ou observação..." value="${escapeHtml(searchValue('transactions'))}"/><button class="secondary" onclick="exportTransactionsMobile()">CSV</button></div><div class="small muted list-count">${rows.length} movimentação(ões)</div><div id="txList">${rows.length?groupedTransactions(rows):'<div class="empty">Nenhuma movimentação encontrada.</div>'}</div><button class="fab" onclick="openNewTransaction()">+</button>`}
function bindTransactions(){const s=$('#txSearch');if(!s)return;s.oninput=()=>{setSearchValue('transactions',s.value);const rows=filteredTransactions();$('#txList').innerHTML=rows.length?groupedTransactions(rows):'<div class="empty">Nenhuma movimentação encontrada.</div>';document.querySelector('.list-count').textContent=`${rows.length} movimentação(ões)`}}
function openNewTransaction(){currentRoute='newtx';render()}
function newTransaction(){const cats=categoryNames(false),accounts=uniqueValues(data.accounts,'name');return `${sectionHead('Novo lançamento',backButton('transactions'))}<div class="card form-card"><div class="segment" id="typeSeg"><button class="active" data-type="expense">Despesa</button><button data-type="income">Receita</button></div><label>Valor</label><input id="txAmount" class="field money-field" inputmode="decimal" placeholder="R$ 0,00"/><label>Descrição</label><input id="txDescription" class="field" placeholder="Ex.: Mercado"/><label>Data</label><input id="txDate" type="date" class="field" value="${isoToday()}"/><label>Conta</label><select id="txAccount" class="field">${accounts.map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select><label>Categoria</label><select id="txCategory" class="field">${cats.map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select><label>Impacta orçamento?</label><select id="txImpact" class="field"><option value="1">Sim</option><option value="0">Não</option></select><label>Transferência entre minhas contas?</label><select id="txOwnTransfer" class="field"><option value="0">Não</option><option value="1">Sim</option></select><label>Observação</label><textarea id="txNotes" class="field" rows="3"></textarea><button class="primary" onclick="saveTransaction()">Salvar lançamento</button></div>`}
function bindTypeSeg(){document.querySelectorAll('#typeSeg button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#typeSeg button').forEach(x=>x.classList.remove('active'));b.classList.add('active')})}
function saveTransaction(){const amount=num($('#txAmount').value),desc=$('#txDescription').value.trim();if(!amount||!desc)return showToast('Informe valor e descrição');const type=document.querySelector('#typeSeg button.active')?.dataset.type||'expense',own=$('#txOwnTransfer').value==='1',id=uid();data.transactions.unshift({id,date:$('#txDate').value||isoToday(),time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),identifier:`MOBILE-${id}`,type,amount:Math.abs(amount),category:$('#txCategory').value,description:desc,account:$('#txAccount').value,impactBudget:own?false:$('#txImpact').value==='1',ownTransfer:own,notes:$('#txNotes').value.trim(),sourceFile:'Lançamento mobile',legacy:false,importedAt:nowIso(),icon:type==='income'?'💼':'🧾'});queueChange('transaction',`${type==='income'?'Receita':'Despesa'} ${fmt(amount)}`);showToast('Lançamento salvo');nav('transactions')}
function openTxActions(id){const x=data.transactions.find(t=>t.id===id);if(!x)return;openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(x.description)}</div><div class="sheet-sub">${brDate(x.date)} • ${escapeHtml(x.category)} • ${fmt(x.amount)}</div>${infoRows([['Conta',escapeHtml(x.account||'')],['Impacta orçamento',boolish(x.impactBudget,true)?'Sim':'Não'],['Transferência própria',boolish(x.ownTransfer)?'Sim':'Não'],['Observação',escapeHtml(x.notes||'—')]])}<div class="sheet-footer stacked"><button class="secondary" onclick="openTxEdit('${id}')">Editar</button><button class="secondary danger" onclick="deleteTransaction('${id}')">Excluir</button><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function openTxEdit(id){const x=data.transactions.find(t=>t.id===id);if(!x)return;const cats=categoryNames(false),accounts=uniqueValues(data.accounts,'name');openModal(`<div class="sheet-handle"></div><div class="sheet-title">Editar movimentação</div><div class="sheet-sub">${brDate(x.date)} • ${fmt(x.amount)}</div><label>Categoria</label><select id="etCategory" class="field">${cats.map(c=>`<option ${c===x.category?'selected':''}>${escapeHtml(c)}</option>`).join('')}</select><label>Conta</label><select id="etAccount" class="field">${accounts.map(c=>`<option ${c===x.account?'selected':''}>${escapeHtml(c)}</option>`).join('')}</select><label>Impacta orçamento?</label><select id="etImpact" class="field"><option value="1" ${boolish(x.impactBudget,true)?'selected':''}>Sim</option><option value="0" ${!boolish(x.impactBudget,true)?'selected':''}>Não</option></select><label>Transferência entre minhas contas?</label><select id="etOwn" class="field"><option value="0" ${!boolish(x.ownTransfer)?'selected':''}>Não</option><option value="1" ${boolish(x.ownTransfer)?'selected':''}>Sim</option></select><label>Observação</label><textarea id="etNotes" class="field" rows="4">${escapeHtml(x.notes||'')}</textarea><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveTxEdit('${id}')">Salvar</button></div>`)}
function saveTxEdit(id){const x=data.transactions.find(t=>t.id===id);if(!x)return;x.category=$('#etCategory').value;x.account=$('#etAccount').value;x.ownTransfer=$('#etOwn').value==='1';x.impactBudget=x.ownTransfer?false:$('#etImpact').value==='1';x.notes=$('#etNotes').value.trim();queueChange('transaction_updated',`Movimentação ${x.description} atualizada`);closeModal();render()}
function deleteTransaction(id){const x=data.transactions.find(t=>t.id===id);if(!x||!confirm('Excluir esta movimentação? Ela poderá aparecer na lixeira do PC após a sincronização.'))return;data.transactions=data.transactions.filter(t=>t.id!==id);queueChange('transaction_deleted',`Movimentação ${x.description} excluída`);closeModal();render()}
function exportTransactionsMobile(){const rows=filteredTransactions(),head=['Data','Valor','Descrição','Categoria','Conta','Impacta orçamento','Transferência própria','Observação'];const body=rows.map(r=>[r.date,signedAmount(r).toFixed(2).replace('.',','),r.description,r.category,r.account,boolish(r.impactBudget,true)?'Sim':'Não',boolish(r.ownTransfer)?'Sim':'Não',r.notes||''].map(csvEscape).join(';'));downloadText(`movimentacoes_${isoToday()}.csv`,[head.join(';'),...body].join('\n'),'text/csv;charset=utf-8');showToast('CSV exportado')}

// ---------------- ORÇAMENTO ----------------
function budget(){const f=getFilters('budget'),y=Number(f.year),m=Number(f.month),all=budgetRows(y,m),rows=all.filter(r=>(f.status==='Todos'||r.status===f.status)&&(f.category==='Todas'||r.category===f.category)),tb=all.reduce((s,x)=>s+x.budget,0),ts=all.reduce((s,x)=>s+x.spent,0);return `${sectionHead('Orçamento','<button class="secondary" onclick="copyPreviousBudgetMobile()">Copiar mês anterior</button>')}${filterBar('budget')}<div class="kpi-grid-3">${kpiHtml('Orçamento total',fmt(tb),'Limite do mês','')}${kpiHtml('Gasto no mês',fmt(ts),'Categorias orçadas','red')}${kpiHtml('Disponível',fmt(tb-ts),'Orçamento − gasto','green')}</div><div class="card">${appCardTitle('Orçamento por categoria','Toque em uma categoria para editar o limite mensal.')}${rows.map(r=>`<div class="budget-row" onclick="editBudget('${encodeURIComponent(r.category)}')"><div><strong>${escapeHtml(r.category)}</strong><div class="small muted">${r.status}${r.essential?' • essencial':''}</div></div><div class="budget-values"><strong>${fmt(r.spent)} / ${fmt(r.budget)}</strong><span class="${r.status==='Estourado'?'expense':r.status==='OK'?'income':''}">${pct(r.used)}</span></div><div class="progress ${r.status==='Atenção'||r.status==='Estourado'?'yellow':'blue'}"><div style="width:${Math.min(100,r.used)}%"></div></div></div>`).join('')||'<div class="empty">Nenhuma categoria para os filtros selecionados.</div>'}</div>`}
function editBudget(enc){const cat=decodeURIComponent(enc),f=getFilters('budget'),r=budgetRows(Number(f.year),Number(f.month)).find(x=>x.category===cat);openModal(`<div class="sheet-handle"></div><div class="sheet-title">Editar orçamento</div><div class="sheet-sub">${escapeHtml(cat)} • ${monthName(f.month)}/${f.year}</div><label>Limite mensal</label><input id="budgetValue" class="field money-field" inputmode="decimal" value="${r?.budget||0}"/><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveBudgetMobile('${encodeURIComponent(cat)}')">Salvar</button></div>`)}
function saveBudgetMobile(enc){const cat=decodeURIComponent(enc),f=getFilters('budget');setBudgetRecord(Number(f.year),Number(f.month),cat,num($('#budgetValue').value));queueChange('budget',`Orçamento ${cat} atualizado`);closeModal();render()}
function copyPreviousBudgetMobile(){const f=getFilters('budget'),y=Number(f.year),m=Number(f.month);if(!confirm(`Copiar os limites de ${monthName(m===1?12:m-1)}/${m===1?y-1:y} para ${monthName(m)}/${y}?`))return;let py=y,pm=m-1;if(pm===0){pm=12;py--}const prev=budgetMap(py,pm);for(const [cat,val] of Object.entries(prev))setBudgetRecord(y,m,cat,val);queueChange('budget_copy',`Orçamento ${monthName(m)}/${y} copiado`);render()}

// ---------------- CONTAS FIXAS ----------------
function filteredRecurring(){const f=getFilters('recurring'),q=searchValue('recurring');return (data.recurring||[]).filter(r=>(f.status==='Todos'||(r.active!==false?'Ativa':'Pausada')===f.status)&&(f.category==='Todas'||r.category===f.category)&&(f.essential==='Todos'||(boolish(r.essential)?'Sim':'Não')===f.essential)&&(f.frequency==='Todas'||r.frequency===f.frequency)&&(f.account==='Todas'||r.account===f.account)&&matchSearch(r,q))}
function recurring(){const rows=filteredRecurring(),s=recurringSummary();return `${sectionHead('Contas fixas','<button class="circle-add" onclick="openRecurringForm()">+</button>')}${filterBar('recurring')}<input id="recSearch" class="search" placeholder="Pesquisar nome, categoria, conta ou status..." value="${escapeHtml(searchValue('recurring'))}"/><div class="kpi-grid-3">${kpiHtml('Fixos / mês',fmt(s.monthly),'Todos os recorrentes ativos','')}${kpiHtml('Essenciais / mês',fmt(s.essential),'Base de segurança','purple')}${kpiHtml('Itens ativos',String(s.count),'Compromissos cadastrados','green')}</div>${rows.map(r=>`<div class="card"><div class="row-between"><div><div class="goal-name">${escapeHtml(r.name)}</div><div class="muted small">${escapeHtml(r.category)} • vence dia ${r.dueDay||'—'} • ${escapeHtml(r.frequency)}${r.essential?' • essencial':''}</div></div><strong>${fmt(r.amount)}</strong></div><div class="small muted" style="margin-top:6px">${escapeHtml(r.account||'Sem conta definida')}${r.notes?` • ${escapeHtml(r.notes)}`:''}</div><div class="actions-row" style="margin-top:10px"><button class="secondary" onclick="openRecurringForm('${r.id}')">Editar</button><button class="secondary" onclick="toggleRecurring('${r.id}')">${r.active!==false?'Pausar':'Ativar'}</button><button class="secondary danger" onclick="deleteRecurring('${r.id}')">Excluir</button></div></div>`).join('')||'<div class="empty">Nenhuma conta fixa encontrada.</div>'}`}
function bindRecurringSearch(){const s=$('#recSearch');if(s)s.oninput=()=>{setSearchValue('recurring',s.value);render()}}
function openRecurringForm(id=''){const r=id?data.recurring.find(x=>x.id===id):null;openModal(`<div class="sheet-handle"></div><div class="sheet-title">${r?'Editar':'Nova'} conta fixa</div><label>Nome</label><input id="rcName" class="field" value="${escapeHtml(r?.name||'')}"/><label>Categoria</label><select id="rcCat" class="field">${categoryNames(false).map(c=>`<option ${c===r?.category?'selected':''}>${escapeHtml(c)}</option>`).join('')}</select><label>Valor</label><input id="rcAmount" class="field" inputmode="decimal" value="${r?.amount||0}"/><div class="sheet-row"><div><label>Dia do vencimento</label><input id="rcDue" class="field" inputmode="numeric" value="${r?.dueDay||0}"/></div><div><label>Frequência</label><select id="rcFreq" class="field">${['Mensal','Anual','Semanal'].map(x=>`<option ${x===(r?.frequency||'Mensal')?'selected':''}>${x}</option>`).join('')}</select></div></div><label>Essencial?</label><select id="rcEss" class="field"><option value="1" ${r?.essential!==false?'selected':''}>Sim</option><option value="0" ${r?.essential===false?'selected':''}>Não</option></select><label>Conta</label><select id="rcAccount" class="field"><option value="">Sem conta</option>${uniqueValues(data.accounts,'name').map(x=>`<option ${x===r?.account?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select><label>Observação</label><textarea id="rcNotes" class="field" rows="3">${escapeHtml(r?.notes||'')}</textarea><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveRecurring('${id}')">Salvar</button></div>`)}
function saveRecurring(id){const name=$('#rcName').value.trim();if(!name)return showToast('Informe o nome');const obj={id:id||uid(),name,category:$('#rcCat').value,amount:num($('#rcAmount').value),dueDay:clamp(parseInt($('#rcDue').value||0),0,31),frequency:$('#rcFreq').value,essential:$('#rcEss').value==='1',active:id?(data.recurring.find(x=>x.id===id)?.active!==false):true,account:$('#rcAccount').value,notes:$('#rcNotes').value.trim()};if(id)Object.assign(data.recurring.find(x=>x.id===id),obj);else data.recurring.unshift(obj);queueChange('recurring',`${id?'Conta fixa atualizada':'Conta fixa adicionada'}: ${name}`);closeModal();render()}
function toggleRecurring(id){const r=data.recurring.find(x=>x.id===id);if(!r)return;r.active=!boolish(r.active,true);queueChange('recurring_status',`${r.name}: ${r.active?'ativa':'pausada'}`);render()}
function deleteRecurring(id){const r=data.recurring.find(x=>x.id===id);if(r&&confirm(`Excluir a conta fixa “${r.name}”?`)){data.recurring=data.recurring.filter(x=>x.id!==id);queueChange('recurring_deleted',`Conta fixa ${r.name} excluída`);render()}}

// ---------------- DÍVIDAS ----------------
function filteredDebts(){const f=getFilters('debts'),q=searchValue('debts');return (data.debts||[]).filter(d=>(f.status==='Todos'||String(d.status||'EM ABERTO')===f.status)&&(f.creditor==='Todos'||d.creditor===f.creditor)&&(f.debtType==='Todos'||d.debtType===f.debtType)&&(f.priority==='Todos'||String(d.priority)===String(f.priority))&&matchSearch(d,q))}
function debts(){const rows=filteredDebts(),s=debtSummary();return `${sectionHead('Dívidas','<button class="circle-add" onclick="openDebtForm()">+</button>')}${filterBar('debts')}<input id="debtSearch" class="search" placeholder="Pesquisar dívida, credor, status..." value="${escapeHtml(searchValue('debts'))}"/><div class="kpi-grid-2">${kpiHtml('Saldo devedor',fmt(s.balance),`${s.count} em aberto`,'red')}${kpiHtml('Parcelas / mês',fmt(s.monthly),'Compromisso mensal','')}${kpiHtml('Total original',fmt(s.original),'Valor contratado','')}${kpiHtml('Comprometimento',pct(s.commitment),'Parcelas ÷ renda','purple')}</div><div class="actions-row top-actions"><button class="secondary" onclick="openDebtStrategy()">Estratégia</button></div>${rows.map(d=>{const p=d.original?Math.max(0,Math.min(100,(1-Number(d.balance)/Number(d.original))*100)):0;return `<div class="card"><div class="row-between"><div><div class="goal-name">${escapeHtml(d.item)}</div><div class="muted small">${escapeHtml(d.creditor||'')} • ${escapeHtml(d.debtType||'')} • prioridade ${d.priority||3}</div></div><span class="chip ${String(d.status).toUpperCase()==='QUITADA'?'green':'yellow'}">${escapeHtml(d.status||'EM ABERTO')}</span></div><div class="detail-kpis" style="margin-top:12px"><div class="mini-kpi"><small>Saldo</small><strong>${fmt(d.balance)}</strong></div><div class="mini-kpi"><small>Parcela</small><strong>${fmt(d.payment)}</strong></div><div class="mini-kpi"><small>Juros</small><strong>${pct(d.interest)}</strong></div></div><div class="progress" style="margin-top:12px"><div style="width:${p}%"></div></div><div class="goal-meta"><span>${d.paidInstallments||0}/${d.totalInstallments||0} parcelas</span><span>Vence dia ${d.dueDay||'—'}</span></div><div class="actions-row" style="margin-top:10px"><button class="secondary" onclick="openDebtActions('${d.id}')">Ações</button><button class="secondary" onclick="openDebtHistory('${d.id}')">Histórico</button></div></div>`}).join('')||'<div class="empty">Nenhuma dívida encontrada.</div>'}`}
function bindDebtSearch(){const s=$('#debtSearch');if(s)s.oninput=()=>{setSearchValue('debts',s.value);render()}}
function debtFieldsHtml(d={}){return `<label>Item</label><input id="dbItem" class="field" value="${escapeHtml(d.item||'')}"/><label>Credor</label><input id="dbCreditor" class="field" value="${escapeHtml(d.creditor||'')}"/><label>Tipo</label><select id="dbType" class="field">${['Parcelamento','Empréstimo','Financiamento','Cartão','Outro'].map(x=>`<option ${x===(d.debtType||'Parcelamento')?'selected':''}>${x}</option>`).join('')}</select><div class="sheet-row"><div><label>Valor original</label><input id="dbOriginal" class="field" inputmode="decimal" value="${d.original||0}"/></div><div><label>Saldo atual</label><input id="dbBalance" class="field" inputmode="decimal" value="${d.balance||0}"/></div></div><label>Parcela mensal</label><input id="dbPayment" class="field" inputmode="decimal" value="${d.payment||0}"/><div class="sheet-row"><div><label>Nº parcelas</label><input id="dbTotal" class="field" inputmode="numeric" value="${d.totalInstallments||0}"/></div><div><label>Pagas</label><input id="dbPaid" class="field" inputmode="numeric" value="${d.paidInstallments||0}"/></div></div><div class="sheet-row"><div><label>Dia vencimento</label><input id="dbDue" class="field" inputmode="numeric" value="${d.dueDay||0}"/></div><div><label>Juros (%)</label><input id="dbInterest" class="field" inputmode="decimal" value="${d.interest||0}"/></div></div><label>Prioridade (1–5)</label><input id="dbPriority" class="field" inputmode="numeric" value="${d.priority||3}"/><label>Observação</label><textarea id="dbNotes" class="field" rows="3">${escapeHtml(d.notes||'')}</textarea>`}
function openDebtForm(id=''){const d=id?data.debts.find(x=>x.id===id):{};openModal(`<div class="sheet-handle"></div><div class="sheet-title">${id?'Editar':'Nova'} dívida</div>${debtFieldsHtml(d)}<div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveDebtForm('${id}')">Salvar</button></div>`)}
function saveDebtForm(id){const item=$('#dbItem').value.trim();if(!item)return showToast('Informe o item');const obj={id:id||uid(),item,creditor:$('#dbCreditor').value.trim(),debtType:$('#dbType').value,original:num($('#dbOriginal').value),balance:num($('#dbBalance').value),payment:num($('#dbPayment').value),totalInstallments:Math.max(0,parseInt($('#dbTotal').value||0)),paidInstallments:Math.max(0,parseInt($('#dbPaid').value||0)),dueDay:clamp(parseInt($('#dbDue').value||0),0,31),interest:Math.max(0,num($('#dbInterest').value)),priority:clamp(parseInt($('#dbPriority').value||3),1,5),status:num($('#dbBalance').value)<=.005?'QUITADA':'EM ABERTO',notes:$('#dbNotes').value.trim(),payments:id?(data.debts.find(x=>x.id===id)?.payments||[]):[]};if(id)Object.assign(data.debts.find(x=>x.id===id),obj);else data.debts.unshift(obj);queueChange('debt',`${id?'Dívida atualizada':'Dívida adicionada'}: ${item}`);closeModal();render()}
function openDebtActions(id){const d=data.debts.find(x=>x.id===id);if(!d)return;openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(d.item)}</div><div class="sheet-sub">Saldo ${fmt(d.balance)} • parcela ${fmt(d.payment)}</div><div class="action-list"><button class="secondary" onclick="openDebtForm('${id}')">Editar cadastro</button><button class="secondary" onclick="openDebtPayment('${id}')">Registrar parcela</button><button class="secondary" onclick="openDebtBalance('${id}')">Atualizar saldo</button><button class="secondary" onclick="openDebtAmortize('${id}')">Amortizar extra</button><button class="secondary" onclick="openDebtSimulation('${id}')">Simular amortização</button><button class="secondary danger" onclick="deleteDebt('${id}')">Excluir</button></div><div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function openDebtPayment(id,type='Parcela'){const d=data.debts.find(x=>x.id===id);closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Registrar pagamento</div><div class="sheet-sub">${escapeHtml(d.item)}</div><label>Valor pago</label><input id="dpAmount" class="field" inputmode="decimal" value="${type==='Parcela'?d.payment:0}"/><label>Tipo</label><select id="dpType" class="field">${['Parcela','Amortização','Quitação','Outro'].map(x=>`<option ${x===type?'selected':''}>${x}</option>`).join('')}</select><label>Data</label><input id="dpDate" type="date" class="field" value="${isoToday()}"/><label>Observação</label><textarea id="dpNotes" class="field" rows="3"></textarea><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveDebtPayment('${id}')">Registrar</button></div>`)}
function saveDebtPayment(id){const d=data.debts.find(x=>x.id===id),amount=Math.min(Math.max(0,num($('#dpAmount').value)),Number(d.balance||0)),type=$('#dpType').value;if(!amount)return showToast('Informe um valor');d.balance=Math.max(0,Number(d.balance)-amount);if(type==='Parcela')d.paidInstallments=Number(d.paidInstallments||0)+1;d.status=d.balance<=.005?'QUITADA':'EM ABERTO';d.payments??=[];d.payments.unshift({id:uid(),date:$('#dpDate').value||isoToday(),amount,type,note:$('#dpNotes').value.trim()});queueChange('debt_payment',`${d.item}: ${type} ${fmt(amount)}`);closeModal();render()}
function openDebtBalance(id){const d=data.debts.find(x=>x.id===id);closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Atualizar saldo</div><label>Novo saldo devedor</label><input id="dbNewBalance" class="field money-field" inputmode="decimal" value="${d.balance}"/><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveDebtBalance('${id}')">Atualizar</button></div>`)}
function saveDebtBalance(id){const d=data.debts.find(x=>x.id===id);d.balance=Math.max(0,num($('#dbNewBalance').value));d.status=d.balance<=.005?'QUITADA':'EM ABERTO';queueChange('debt_balance',`${d.item}: saldo atualizado`);closeModal();render()}
function openDebtAmortize(id){closeModal();openDebtPayment(id,'Amortização')}
function openDebtSimulation(id){const d=data.debts.find(x=>x.id===id);closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Simular amortização</div><label>Valor extra</label><input id="simExtra" class="field money-field" inputmode="decimal" value="0"/><button class="primary" onclick="runDebtSimulation('${id}')">Simular</button><div id="debtSimResult"></div><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Fechar</button></div>`)}
function runDebtSimulation(id){const d=data.debts.find(x=>x.id===id),r=simulateDebtExtraPaymentJS(d,num($('#simExtra').value));$('#debtSimResult').innerHTML=`<div class="card soft-card" style="margin-top:12px">${infoRows([['Prazo atual',r.months_before===null?'Não calculável':`${r.months_before} meses`],['Com amortização',r.months_after===null?'Não calculável':`${r.months_after} meses`],['Juros antes',fmt(r.interest_before)],['Juros depois',fmt(r.interest_after)],['Economia estimada',fmt(r.saved_interest)]])}</div>`}
function openDebtHistory(id){const d=data.debts.find(x=>x.id===id);openModal(`<div class="sheet-handle"></div><div class="sheet-title">Histórico — ${escapeHtml(d.item)}</div>${(d.payments||[]).map(p=>`<div class="tx"><div class="tx-icon">✓</div><div><div class="tx-title">${escapeHtml(p.type||'Pagamento')}</div><div class="tx-sub">${brDate(p.date)} • ${escapeHtml(p.note||'')}</div></div><strong>${fmt(p.amount)}</strong></div>`).join('')||'<div class="empty">Nenhum pagamento registrado.</div>'}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function openDebtStrategy(){const active=(data.debts||[]).filter(x=>Number(x.balance)>0.005),snow=[...active].sort((a,b)=>Number(a.balance)-Number(b.balance)||Number(b.interest)-Number(a.interest)),ava=[...active].sort((a,b)=>Number(b.interest)-Number(a.interest)||Number(a.balance)-Number(b.balance));openModal(`<div class="sheet-handle"></div><div class="sheet-title">Estratégia de quitação</div><div class="card soft-card"><div class="section-title">Bola de neve</div><div class="muted small">Menor saldo primeiro.</div>${snow.map(x=>`<div class="info-row"><span>${escapeHtml(x.item)}</span><strong>${fmt(x.balance)}</strong></div>`).join('')}</div><div class="card soft-card"><div class="section-title">Avalanche</div><div class="muted small">Maior taxa de juros primeiro.</div>${ava.map(x=>`<div class="info-row"><span>${escapeHtml(x.item)}</span><strong>${pct(x.interest)} • ${fmt(x.balance)}</strong></div>`).join('')}</div><div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function deleteDebt(id){const d=data.debts.find(x=>x.id===id);if(d&&confirm(`Excluir a dívida “${d.item}”?`)){data.debts=data.debts.filter(x=>x.id!==id);queueChange('debt_deleted',`Dívida ${d.item} excluída`);closeModal();render()}}

// ---------------- INVESTIMENTOS ----------------
function filteredInvestments(){const f=getFilters('investments'),q=searchValue('investments');return (data.investments||[]).filter(a=>{if(f.kind!=='Todos'&&String(a.kind||'')!==f.kind)return false;if(f.assetClass!=='Todos'&&String(a.type||'')!==f.assetClass)return false;if(f.institution!=='Todos'&&String(a.institution||'')!==f.institution)return false;return matchSearch(a,q)})}
function investments(){const s=investmentSummary(),rows=filteredInvestments(),alloc=Object.entries(s.allocation||{}).sort((a,b)=>b[1]-a[1]);return `${sectionHead('Investimentos','<button class="circle-add" onclick="openInvestmentForm()">+</button>')}${filterBar('investments')}<div class="search-row"><input id="investmentSearch" class="search" placeholder="Buscar ativo, ticker, classe ou instituição..." value="${escapeHtml(searchValue('investments'))}"/><button class="secondary" onclick="openInvestmentLedgerOverview()">Extrato</button></div><div class="kpi-grid-2">${kpiHtml('Valor atual',fmt(s.market),`${s.count} ativos`,'green')}${kpiHtml('Custo / aplicado',fmt(s.cost),'Capital investido','')}${kpiHtml('Resultado',fmt(s.gain),pct(s.gain_pct),s.gain>=0?'green':'red')}${kpiHtml('Rendimentos',fmt(s.income),'Proventos registrados','purple')}</div><div class="card">${appCardTitle('Alocação por classe')}${simpleBars(alloc,12)}</div><div class="card"><div class="row-between"><div class="section-title">Carteira</div><span class="chip blue">${rows.length} ativo(s)</span></div>${rows.map(a=>{const cost=investmentCost(a),market=investmentMarket(a),gain=market-cost,gp=cost?gain/cost*100:0;return `<div class="entity-card" onclick="openInvestmentActions('${a.id}')"><div class="row-between"><div><div class="goal-name">${escapeHtml(a.name)}</div><div class="tx-sub">${escapeHtml(a.ticker||'Sem ticker')} • ${escapeHtml(a.kind||'')} • ${escapeHtml(a.type||'Outros')}</div></div><span class="chip ${gain>=0?'green':'yellow'}">${pct(gp)}</span></div><div class="detail-kpis" style="margin-top:10px"><div class="mini-kpi"><small>Custo</small><strong>${fmt(cost)}</strong></div><div class="mini-kpi"><small>Atual</small><strong>${fmt(market)}</strong></div><div class="mini-kpi"><small>Resultado</small><strong class="${gain>=0?'income':'expense'}">${fmt(gain)}</strong></div></div><div class="goal-meta"><span>${escapeHtml(a.institution||'Sem instituição')}</span><span>Meta ${pct(a.targetPct||0)}</span></div></div>`}).join('')||'<div class="empty">Nenhum investimento encontrado.</div>'}</div>`}
function bindInvestmentSearch(){const s=$('#investmentSearch');if(s)s.oninput=()=>{setSearchValue('investments',s.value);render()}}
function investmentFormHtml(a={}){const kind=a.kind||'Renda variável';const classes=['Ações','FIIs','ETF','Tesouro Direto','CDB / RDB','LCI / LCA','Cripto','Caixa','Outros'];return `<label>Modalidade</label><select id="ivKind" class="field">${['Renda variável','Renda fixa'].map(x=>`<option ${String(kind).toLowerCase()===x.toLowerCase()?'selected':''}>${x}</option>`).join('')}</select><label>Nome</label><input id="ivName" class="field" value="${escapeHtml(a.name||'')}"/><label>Ticker</label><input id="ivTicker" class="field" value="${escapeHtml(a.ticker||'')}"/><label>Classe</label><select id="ivClass" class="field">${classes.map(x=>`<option ${x===(a.type||'Outros')?'selected':''}>${x}</option>`).join('')}</select><label>Instituição</label><input id="ivInstitution" class="field" value="${escapeHtml(a.institution||'')}"/><label>Meta de alocação (%)</label><input id="ivTarget" class="field" inputmode="decimal" value="${a.targetPct||0}"/><details class="form-details" open><summary>Valores e posição</summary><div class="sheet-row"><div><label>Quantidade</label><input id="ivQty" class="field" inputmode="decimal" value="${a.quantity||0}"/></div><div><label>Preço médio</label><input id="ivAvg" class="field" inputmode="decimal" value="${a.avgPrice||0}"/></div></div><label>Preço atual</label><input id="ivPrice" class="field" inputmode="decimal" value="${a.currentPrice||0}"/><div class="sheet-row"><div><label>Valor aplicado (renda fixa)</label><input id="ivPrincipal" class="field" inputmode="decimal" value="${a.invested||0}"/></div><div><label>Valor atual (renda fixa)</label><input id="ivCurrent" class="field" inputmode="decimal" value="${a.current||0}"/></div></div></details><details class="form-details"><summary>Renda fixa e tributação</summary><label>Data da aplicação</label><input id="ivDate" type="date" class="field" value="${a.investedDate||''}"/><label>Vencimento</label><input id="ivMaturity" type="date" class="field" value="${a.maturity||''}"/><label>Indexador / taxa</label><input id="ivIndexer" class="field" value="${escapeHtml(a.indexer||'')}"/><div class="sheet-row"><div><label>Taxa contratada</label><input id="ivRate" class="field" inputmode="decimal" value="${a.rate||0}"/></div><div><label>% benchmark</label><input id="ivBenchmark" class="field" inputmode="decimal" value="${a.benchmarkPct??100}"/></div></div><div class="sheet-row"><div><label>Custos acumulados</label><input id="ivFees" class="field" inputmode="decimal" value="${a.fees||0}"/></div><div><label>IR estimado (%)</label><input id="ivTax" class="field" inputmode="decimal" value="${a.taxRate||0}"/></div></div></details><label>Observação</label><textarea id="ivNotes" class="field" rows="3">${escapeHtml(a.notes||'')}</textarea>`}
function openInvestmentForm(id=''){const a=id?(data.investments||[]).find(x=>x.id===id):{};openModal(`<div class="sheet-handle"></div><div class="sheet-title">${id?'Editar':'Novo'} investimento</div><div class="sheet-sub">Os campos avançados são os mesmos disponíveis no desktop.</div>${investmentFormHtml(a)}<div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveInvestmentForm('${id}')">Salvar</button></div>`)}
function saveInvestmentForm(id){const name=$('#ivName').value.trim();if(!name)return showToast('Informe o nome do investimento');const old=id?data.investments.find(x=>x.id===id):null,obj={id:id||uid(),name,ticker:$('#ivTicker').value.trim(),kind:$('#ivKind').value,type:$('#ivClass').value,institution:$('#ivInstitution').value.trim(),targetPct:clamp(num($('#ivTarget').value),0,100),quantity:Math.max(0,num($('#ivQty').value)),avgPrice:Math.max(0,num($('#ivAvg').value)),currentPrice:Math.max(0,num($('#ivPrice').value)),invested:Math.max(0,num($('#ivPrincipal').value)),current:Math.max(0,num($('#ivCurrent').value)),investedDate:$('#ivDate').value,maturity:$('#ivMaturity').value,indexer:$('#ivIndexer').value.trim(),rate:num($('#ivRate').value),benchmarkPct:num($('#ivBenchmark').value),fees:Math.max(0,num($('#ivFees').value)),taxRate:clamp(num($('#ivTax').value),0,100),notes:$('#ivNotes').value.trim(),history:old?.history||[],incomeHistory:old?.incomeHistory||[]};if(id)Object.assign(old,obj);else data.investments.unshift(obj);queueChange('investment',`${id?'Investimento atualizado':'Investimento criado'}: ${name}`);closeModal();render()}
function openInvestmentActions(id){const a=data.investments.find(x=>x.id===id);if(!a)return;const cost=investmentCost(a),market=investmentMarket(a);openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(a.name)}</div><div class="sheet-sub">${escapeHtml(a.ticker||'')} • ${escapeHtml(a.kind||'')} • Atual ${fmt(market)} • custo ${fmt(cost)}</div><div class="action-list"><button class="secondary" onclick="openInvestmentForm('${id}')">Editar cadastro completo</button><button class="secondary" onclick="openInvestmentValue('${id}')">Atualizar valor / preço</button><button class="secondary" onclick="openInvestmentIncome('${id}')">Registrar rendimento</button><button class="secondary" onclick="openInvestmentEvent('${id}')">Registrar evento</button><button class="secondary" onclick="openInvestmentLedger('${id}')">Extrato completo</button><button class="secondary danger" onclick="deleteInvestment('${id}')">Excluir investimento</button></div><div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function openInvestmentValue(id){const a=data.investments.find(x=>x.id===id),fixed=String(a.kind||'').toLowerCase()==='renda fixa';closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Atualizar ${fixed?'valor':'preço'}</div><div class="sheet-sub">${escapeHtml(a.name)}</div><label>${fixed?'Novo valor atual':'Novo preço atual'}</label><input id="ivNewValue" class="field money-field" inputmode="decimal" value="${fixed?a.current:a.currentPrice}"/><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveInvestmentValue('${id}')">Atualizar</button></div>`)}
function saveInvestmentValue(id){const a=data.investments.find(x=>x.id===id),v=Math.max(0,num($('#ivNewValue').value));if(String(a.kind||'').toLowerCase()==='renda fixa')a.current=v;else a.currentPrice=v;queueChange('investment_value',`${a.name}: valor atualizado`);closeModal();render()}
function openInvestmentIncome(id){const a=data.investments.find(x=>x.id===id);closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Registrar rendimento</div><div class="sheet-sub">${escapeHtml(a.name)}</div><label>Data</label><input id="iiDate" type="date" class="field" value="${isoToday()}"/><label>Tipo</label><select id="iiType" class="field">${['Provento','Dividendo','JCP','Cupom','Rendimento','Outro'].map(x=>`<option>${x}</option>`).join('')}</select><label>Valor</label><input id="iiAmount" class="field money-field" inputmode="decimal" value="0"/><label>Observação</label><textarea id="iiNotes" class="field" rows="3"></textarea><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveInvestmentIncome('${id}')">Registrar</button></div>`)}
function saveInvestmentIncome(id){const a=data.investments.find(x=>x.id===id),amount=Math.max(0,num($('#iiAmount').value));if(!amount)return showToast('Informe um valor');a.incomeHistory??=[];a.incomeHistory.unshift({id:uid(),date:$('#iiDate').value,type:$('#iiType').value,amount,note:$('#iiNotes').value.trim()});queueChange('investment_income',`${a.name}: rendimento ${fmt(amount)}`);closeModal();render()}
function openInvestmentEvent(id){const a=data.investments.find(x=>x.id===id);closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Novo evento</div><div class="sheet-sub">${escapeHtml(a.name)}</div><label>Data</label><input id="ieDate" type="date" class="field" value="${isoToday()}"/><label>Tipo</label><select id="ieType" class="field">${['Aplicação','Compra','Venda','Resgate','Rendimento','Ajuste de saldo','Provento'].map(x=>`<option>${x}</option>`).join('')}</select><label>Valor</label><input id="ieAmount" class="field" inputmode="decimal" value="0"/><label>Quantidade</label><input id="ieQty" class="field" inputmode="decimal" value="0"/><label>Preço unitário</label><input id="iePrice" class="field" inputmode="decimal" value="0"/><label>Observação</label><textarea id="ieNotes" class="field" rows="3"></textarea><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveInvestmentEvent('${id}')">Registrar</button></div>`)}
function saveInvestmentEvent(id){const a=data.investments.find(x=>x.id===id),type=$('#ieType').value,amount=num($('#ieAmount').value),qty=Math.max(0,num($('#ieQty').value)),price=Math.max(0,num($('#iePrice').value)),fixed=String(a.kind||'').toLowerCase()==='renda fixa';if(fixed){if(['Aplicação','Compra'].includes(type)){a.invested=Number(a.invested||0)+Math.max(0,amount);a.current=Number(a.current||0)+Math.max(0,amount)}else if(['Venda','Resgate'].includes(type))a.current=Math.max(0,Number(a.current||0)-Math.abs(amount));else if(['Rendimento','Provento','Ajuste de saldo'].includes(type))a.current=Math.max(0,Number(a.current||0)+amount)}else{if(['Aplicação','Compra'].includes(type)){const oldQty=Number(a.quantity||0),oldCost=oldQty*Number(a.avgPrice||0),eventCost=qty*(price||0)||Math.max(0,amount),addQty=qty||(price>0?Math.max(0,amount)/price:0);a.quantity=oldQty+addQty;if(a.quantity>0)a.avgPrice=(oldCost+eventCost)/a.quantity;if(price>0)a.currentPrice=price}else if(['Venda','Resgate'].includes(type)){const remove=qty||(price>0?Math.abs(amount)/price:0);a.quantity=Math.max(0,Number(a.quantity||0)-remove);if(price>0)a.currentPrice=price}else if(type==='Ajuste de saldo'&&price>0)a.currentPrice=price}a.history??=[];a.history.unshift({id:uid(),date:$('#ieDate').value,type,amount,quantity:qty,unitPrice:price,note:$('#ieNotes').value.trim(),createdAt:nowIso()});queueChange('investment_event',`${a.name}: ${type}`);closeModal();render()}
function openInvestmentLedger(id){const a=data.investments.find(x=>x.id===id);closeModal();const events=(a.history||[]).map(x=>({...x,_kind:'Evento'})),incomes=(a.incomeHistory||[]).map(x=>({id:x.id,date:x.date,type:x.type,amount:x.amount,quantity:0,unitPrice:0,note:x.note,_kind:'Rendimento'})),rows=[...events,...incomes].sort((x,y)=>String(y.date||'').localeCompare(String(x.date||'')));openModal(`<div class="sheet-handle"></div><div class="sheet-title">Extrato — ${escapeHtml(a.name)}</div>${rows.map(x=>`<div class="tx"><div class="tx-icon">${x._kind==='Rendimento'?'$':'↕'}</div><div><div class="tx-title">${escapeHtml(x.type||x._kind)}</div><div class="tx-sub">${brDate(x.date)}${x.quantity?` • Qtd ${Number(x.quantity).toLocaleString('pt-BR',{maximumFractionDigits:8})}`:''}${x.unitPrice?` • ${fmt(x.unitPrice)}`:''}${x.note?` • ${escapeHtml(x.note)}`:''}</div></div><strong class="${Number(x.amount)>=0?'income':'expense'}">${fmt(x.amount)}</strong></div>`).join('')||'<div class="empty">Nenhum evento registrado.</div>'}<div class="sheet-footer"><button class="secondary" onclick="openInvestmentEvent('${id}')">Novo evento</button><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function openInvestmentLedgerOverview(){const rows=(data.investments||[]).flatMap(a=>(a.history||[]).map(e=>({...e,asset:a.name}))).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,150);openModal(`<div class="sheet-handle"></div><div class="sheet-title">Extrato da carteira</div><div class="sheet-sub">Últimos eventos de todos os investimentos.</div>${rows.map(x=>`<div class="tx"><div class="tx-icon">↕</div><div><div class="tx-title">${escapeHtml(x.asset)} • ${escapeHtml(x.type)}</div><div class="tx-sub">${brDate(x.date)} • ${escapeHtml(x.note||'')}</div></div><strong>${fmt(x.amount)}</strong></div>`).join('')||'<div class="empty">Sem eventos.</div>'}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function deleteInvestment(id){const a=data.investments.find(x=>x.id===id);if(a&&confirm(`Excluir o investimento “${a.name}”?`)){data.investments=data.investments.filter(x=>x.id!==id);queueChange('investment_deleted',`Investimento ${a.name} excluído`);closeModal();render()}}

// ---------------- CALCULADORA ----------------
function calcTab(){return state.meta.calcTab||'simple'}
function setCalcTab(tab){state.meta.calcTab=tab;save();render()}
function calculator(){const tab=calcTab();return `${sectionHead('Calculadora','<button class="secondary" onclick="openScenarioManager()">Cenários</button>')}<div class="segment"><button class="${tab==='simple'?'active':''}" onclick="setCalcTab('simple')">Simples</button><button class="${tab==='advanced'?'active':''}" onclick="setCalcTab('advanced')">Completa</button><button class="${tab==='scenarios'?'active':''}" onclick="setCalcTab('scenarios')">Cenários</button></div><div id="calcBody">${tab==='simple'?simpleCalcForm():tab==='advanced'?completeCalcForm():scenarioPage()}</div>`}
function simpleCalcForm(){const p=state.meta.simpleCalc||{name:'Objetivo',target:500,initial:0,contribution:25,frequency:'Semanal',rate:0};return `<div class="card form-card"><div class="section-title">Objetivo de compra</div><div class="muted small">Mesma lógica da calculadora simples do desktop.</div><label>Nome do objetivo</label><input id="csName" class="field" value="${escapeHtml(p.name||'Objetivo')}"/><label>Preço à vista</label><input id="csTarget" class="field money-field" inputmode="decimal" value="${p.target||0}"/><label>Valor já guardado</label><input id="csInitial" class="field" inputmode="decimal" value="${p.initial||0}"/><label>Valor de cada aporte</label><input id="csContrib" class="field" inputmode="decimal" value="${p.contribution||0}"/><label>Frequência</label><select id="csFreq" class="field">${['Semanal','Mensal','Anual'].map(x=>`<option ${x===(p.frequency||'Semanal')?'selected':''}>${x}</option>`).join('')}</select><label>Rentabilidade ao ano (%)</label><input id="csRate" class="field" inputmode="decimal" value="${p.rate||0}"/><button class="primary" onclick="runSimpleCalc()">Calcular quando consigo comprar</button><button class="secondary full-btn" onclick="saveSimpleCalcGoal()">Cadastrar como meta</button></div><div id="simpleCalcResult">${state.meta.simpleCalcResult?simpleCalcResultHtml(state.meta.simpleCalcResult):''}</div>`}
function readSimpleCalc(){return {name:$('#csName').value.trim()||'Objetivo',target:num($('#csTarget').value),initial:num($('#csInitial').value),contribution:num($('#csContrib').value),frequency:$('#csFreq').value,rate:num($('#csRate').value)}}
function simpleCalcResultHtml(r){return `<div class="card"><div class="section-title">Resultado</div><div style="font-size:34px;font-weight:900;color:var(--green)">${escapeHtml(r.goal_label)}</div><div class="muted" style="margin:5px 0 12px">${escapeHtml(r.friendly_detail)} • data estimada ${escapeHtml(r.goal_date_br)}</div><div class="kpi-grid-2">${kpiHtml('Falta hoje',fmt(Math.max(0,r.target-r.initial)),'Até o preço à vista','')}${kpiHtml('Aportes',r.goal_steps===null?'—':String(r.goal_steps),'Quantidade necessária','')}${kpiHtml('Do seu bolso',fmt(r.goal_invested),'Total guardado','green')}${kpiHtml('Rendimento',fmt(r.goal_interest),'Estimado até a meta','purple')}</div></div>`}
function runSimpleCalc(){try{const p=readSimpleCalc(),r=simulateSavingsGoalJS(p);state.meta.simpleCalc=p;state.meta.simpleCalcResult=r;save();$('#simpleCalcResult').innerHTML=simpleCalcResultHtml(r)}catch(e){showToast(e.message||String(e))}}
function saveSimpleCalcGoal(){try{const p=readSimpleCalc(),r=simulateSavingsGoalJS(p);data.goals.unshift({id:uid(),name:p.name,type:'Compra',target:Math.max(0,p.target),current:Math.max(0,p.initial),deadline:r.goal_date||'',priority:3,note:'Criada pela calculadora de compra à vista',icon:'🎯',history:[]});queueChange('goal_created',`Meta criada: ${p.name}`);showToast('Meta cadastrada')}catch(e){showToast(e.message||String(e))}}
function defaultAdvancedParams(){return {initial:0,years:10,rate:12,rate_phases:'',inflation:4.5,cdi_rate:10,ipca_rate:4.5,ipca_spread:6,fixed_reference:12,fee:0,tax:15,salary:Number(data.settings.monthlyIncome||0),monthly:Number(data.settings.monthlyInvestmentGoal||0),salary_pct:10,salary_growth:5,growth:5,thirteenth:0,thirteenth_pct:100,plr:0,plr_pct:100,vacation_pct:100,annual_extra:0,target:0,withdrawal_rate:.6,skip_months:'',oneoffs:'',monthly_mode:'Valor fixo',thirteenth_month:12,plr_month:3,vacation_month:1}}
function completeCalcForm(){const p={...defaultAdvancedParams(),...(state.meta.advancedCalc||{})};return `<div class="card form-card"><div class="section-title">Simulação completa</div><div class="muted small">Salário, aportes, 13º, PLR, férias, fases de rentabilidade, inflação, custos, IR e metas.</div><details class="form-details" open><summary>Capital, prazo e retorno</summary><label>Valor inicial</label><input id="caInitial" class="field" inputmode="decimal" value="${p.initial}"/><div class="sheet-row"><div><label>Anos</label><input id="caYears" class="field" inputmode="decimal" value="${p.years}"/></div><div><label>Rentabilidade anual (%)</label><input id="caRate" class="field" inputmode="decimal" value="${p.rate}"/></div></div><label>Fases de rentabilidade</label><input id="caPhases" class="field" value="${escapeHtml(p.rate_phases||'')}" placeholder="1-5:12;6-10:10"/><div class="sheet-row"><div><label>Inflação (%)</label><input id="caInflation" class="field" inputmode="decimal" value="${p.inflation}"/></div><div><label>Taxas/custos (%)</label><input id="caFee" class="field" inputmode="decimal" value="${p.fee}"/></div></div><label>Imposto sobre rendimento (%)</label><input id="caTax" class="field" inputmode="decimal" value="${p.tax}"/></details><details class="form-details" open><summary>Aportes e salário</summary><label>Salário mensal</label><input id="caSalary" class="field" inputmode="decimal" value="${p.salary}"/><label>Modo do aporte</label><select id="caMode" class="field"><option ${p.monthly_mode==='Valor fixo'?'selected':''}>Valor fixo</option><option ${p.monthly_mode==='% do salário'?'selected':''}>% do salário</option></select><div class="sheet-row"><div><label>Aporte mensal fixo</label><input id="caMonthly" class="field" inputmode="decimal" value="${p.monthly}"/></div><div><label>% do salário</label><input id="caSalaryPct" class="field" inputmode="decimal" value="${p.salary_pct}"/></div></div><div class="sheet-row"><div><label>Aumento salário a.a. (%)</label><input id="caSalaryGrowth" class="field" inputmode="decimal" value="${p.salary_growth}"/></div><div><label>Crescimento aporte a.a. (%)</label><input id="caGrowth" class="field" inputmode="decimal" value="${p.growth}"/></div></div><label>Meses sem aporte</label><input id="caSkip" class="field" value="${escapeHtml(p.skip_months||'')}" placeholder="1,7"/><label>Aportes pontuais</label><input id="caOneoffs" class="field" value="${escapeHtml(p.oneoffs||'')}" placeholder="6:1000;18:5000"/></details><details class="form-details"><summary>13º, PLR, férias e extras</summary><div class="sheet-row"><div><label>13º fixo</label><input id="ca13" class="field" inputmode="decimal" value="${p.thirteenth}"/></div><div><label>% do 13º investido</label><input id="ca13Pct" class="field" inputmode="decimal" value="${p.thirteenth_pct}"/></div></div><label>Mês do 13º</label><input id="ca13Month" class="field" inputmode="numeric" value="${p.thirteenth_month}"/><div class="sheet-row"><div><label>PLR anual</label><input id="caPlr" class="field" inputmode="decimal" value="${p.plr}"/></div><div><label>% da PLR investida</label><input id="caPlrPct" class="field" inputmode="decimal" value="${p.plr_pct}"/></div></div><label>Mês da PLR</label><input id="caPlrMonth" class="field" inputmode="numeric" value="${p.plr_month}"/><label>% adicional férias investido</label><input id="caVacationPct" class="field" inputmode="decimal" value="${p.vacation_pct}"/><label>Mês das férias</label><input id="caVacationMonth" class="field" inputmode="numeric" value="${p.vacation_month}"/><label>Aporte extra anual</label><input id="caAnnualExtra" class="field" inputmode="decimal" value="${p.annual_extra}"/></details><details class="form-details"><summary>Metas e benchmarks</summary><label>Meta patrimonial</label><input id="caTarget" class="field" inputmode="decimal" value="${p.target}"/><label>Taxa de renda mensal futura (%)</label><input id="caWithdrawal" class="field" inputmode="decimal" value="${p.withdrawal_rate}"/><div class="sheet-row"><div><label>CDI referência (%)</label><input id="caCdi" class="field" inputmode="decimal" value="${p.cdi_rate}"/></div><div><label>IPCA (%)</label><input id="caIpca" class="field" inputmode="decimal" value="${p.ipca_rate}"/></div></div><div class="sheet-row"><div><label>IPCA + taxa (%)</label><input id="caSpread" class="field" inputmode="decimal" value="${p.ipca_spread}"/></div><div><label>Taxa fixa ref. (%)</label><input id="caFixed" class="field" inputmode="decimal" value="${p.fixed_reference}"/></div></div></details><button class="primary" onclick="runAdvancedCalc()">Calcular projeção completa</button><div class="actions-row" style="margin-top:9px"><button class="secondary" onclick="runMonteCarlo()">Monte Carlo</button><button class="secondary" onclick="saveScenarioPrompt()">Salvar cenário</button></div></div><div id="advancedCalcResult">${state.meta.advancedCalcResult?advancedCalcResultHtml(state.meta.advancedCalcResult,state.meta.advancedCalc):''}</div>`}
function readAdvancedCalc(){return {initial:num($('#caInitial').value),years:num($('#caYears').value),rate:num($('#caRate').value),rate_phases:$('#caPhases').value.trim(),inflation:num($('#caInflation').value),fee:num($('#caFee').value),tax:num($('#caTax').value),salary:num($('#caSalary').value),monthly_mode:$('#caMode').value,monthly:num($('#caMonthly').value),salary_pct:num($('#caSalaryPct').value),salary_growth:num($('#caSalaryGrowth').value),growth:num($('#caGrowth').value),skip_months:$('#caSkip').value.trim(),oneoffs:$('#caOneoffs').value.trim(),thirteenth:num($('#ca13').value),thirteenth_pct:num($('#ca13Pct').value),thirteenth_month:num($('#ca13Month').value),plr:num($('#caPlr').value),plr_pct:num($('#caPlrPct').value),plr_month:num($('#caPlrMonth').value),vacation_pct:num($('#caVacationPct').value),vacation_month:num($('#caVacationMonth').value),annual_extra:num($('#caAnnualExtra').value),target:num($('#caTarget').value),withdrawal_rate:num($('#caWithdrawal').value),cdi_rate:num($('#caCdi').value),ipca_rate:num($('#caIpca').value),ipca_spread:num($('#caSpread').value),fixed_reference:num($('#caFixed').value)}}
function advancedCalcResultHtml(r,p={}){const need=p.target>0?requiredMonthlyForTargetJS(p,p.target):0,eta=p.target>0?yearsToTargetJS(p,p.target):null,bench=benchmarkComparisonJS(p);return `<div class="card"><div class="section-title">Resultado da projeção</div><div class="kpi-grid-2">${kpiHtml('Patrimônio líquido',fmt(r.net),`${Number(p.years||0).toLocaleString('pt-BR')} anos`,'green')}${kpiHtml('Em valor real',fmt(r.real_net),'Descontando inflação','')}${kpiHtml('Total investido',fmt(r.invested),'Aportes acumulados','')}${kpiHtml('Rendimento bruto',fmt(r.gross_interest),`IR estimado ${fmt(r.tax_value)}`,'purple')}${kpiHtml('Renda mensal futura',fmt(r.monthly_income),'Pela taxa informada','green')}${kpiHtml('Aporte p/ meta',p.target>0?fmt(need):'—',eta===null?'Meta não atingida no horizonte':eta!==null?`Prazo ≈ ${eta.toFixed(1).replace('.',',')} anos`:'Sem meta','')}</div>${r.points?.length?`<div class="section-title" style="margin-top:16px">Evolução</div>${simpleBars(r.points.map(x=>[`${Math.round(x.month/12)} ano(s)`,x.balance]),12)}`:''}<div class="section-title" style="margin-top:16px">Benchmarks</div>${bench.map(b=>`<div class="info-row"><span>${escapeHtml(b.name)} • ${pct(b.rate)}</span><strong>${fmt(b.result.net)}</strong></div>`).join('')}</div>`}
function runAdvancedCalc(){try{const p=readAdvancedCalc(),r=simulateInvestmentJS(p);state.meta.advancedCalc=p;state.meta.advancedCalcResult=r;save();$('#advancedCalcResult').innerHTML=advancedCalcResultHtml(r,p)}catch(e){showToast(e.message||String(e))}}
function runMonteCarlo(){try{const p=readAdvancedCalc(),sims=prompt('Número de simulações (100 a 2000):','400');if(sims===null)return;const vol=prompt('Volatilidade anual estimada (%):','12');if(vol===null)return;const r=monteCarloJS(p,num(sims),num(vol));openModal(`<div class="sheet-handle"></div><div class="sheet-title">Monte Carlo</div><div class="sheet-sub">Faixas probabilísticas para o patrimônio final.</div><div class="detail-kpis"><div class="mini-kpi"><small>P10</small><strong>${fmt(r.p10)}</strong></div><div class="mini-kpi"><small>Mediana P50</small><strong>${fmt(r.p50)}</strong></div><div class="mini-kpi"><small>P90</small><strong>${fmt(r.p90)}</strong></div></div>${infoRows([['Simulações',String(r.simulations)],['Volatilidade',pct(r.volatility_pct)]])}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}catch(e){showToast(e.message||String(e))}}
function normalizeScenario(s){return {id:s.id||uid(),name:s.name||'Cenário',params:parseJsonMaybe(s.params_json??s.params,{}),results:parseJsonMaybe(s.results_json??s.results,{}),createdAt:s.created_at||s.createdAt||nowIso(),updatedAt:s.updated_at||s.updatedAt||nowIso()}}
function scenarioPage(){const ss=(data.scenarios||[]).map(normalizeScenario);return `<div class="card"><div class="row-between"><div><div class="section-title">Cenários salvos</div><div class="muted small">Salvar, carregar, duplicar, comparar e excluir.</div></div><button class="secondary" onclick="saveScenarioPrompt()">Salvar atual</button></div>${ss.map(s=>`<div class="entity-card"><div class="row-between"><div><div class="goal-name">${escapeHtml(s.name)}</div><div class="tx-sub">${s.params.years||'—'} anos • ${pct(s.params.rate||0)} a.a. • ${fmt(s.results.net||0)}</div></div><button class="link-btn" onclick="openScenarioActions('${s.id}')">Ações</button></div></div>`).join('')||'<div class="empty">Nenhum cenário salvo.</div>'}<button class="secondary full-btn" onclick="openScenarioCompare()">Comparar cenários</button></div>`}
function saveScenarioPrompt(){let p;try{p=currentRoute==='calculator'&&calcTab()==='advanced'&&$('#caInitial')?readAdvancedCalc():(state.meta.advancedCalc||defaultAdvancedParams())}catch{p=state.meta.advancedCalc||defaultAdvancedParams()}const r=simulateInvestmentJS(p),name=prompt('Nome do cenário:','Meu cenário');if(!name)return;const existing=(data.scenarios||[]).find(x=>(x.name||'').toLocaleLowerCase('pt-BR')===name.trim().toLocaleLowerCase('pt-BR')),raw={id:existing?.id||uid(),name:name.trim(),params_json:JSON.stringify(p),results_json:JSON.stringify({...r,points:undefined}),created_at:existing?.created_at||nowIso(),updated_at:nowIso()};if(existing)Object.assign(existing,raw);else data.scenarios.unshift(raw);queueChange('scenario',`Cenário salvo: ${name.trim()}`);showToast('Cenário salvo');if(calcTab()==='scenarios')render()}
function openScenarioManager(){setCalcTab('scenarios')}
function openScenarioActions(id){const raw=(data.scenarios||[]).find(x=>x.id===id),s=normalizeScenario(raw);openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(s.name)}</div>${infoRows([['Patrimônio projetado',fmt(s.results.net||0)],['Prazo',`${s.params.years||0} anos`],['Rentabilidade',pct(s.params.rate||0)],['Aporte mensal',fmt(s.params.monthly||0)]])}<div class="action-list"><button class="secondary" onclick="loadScenario('${id}')">Carregar na calculadora</button><button class="secondary" onclick="duplicateScenario('${id}')">Duplicar</button><button class="secondary danger" onclick="deleteScenarioMobile('${id}')">Excluir</button></div><div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function loadScenario(id){const raw=data.scenarios.find(x=>x.id===id),s=normalizeScenario(raw);state.meta.advancedCalc=s.params;state.meta.advancedCalcResult=simulateInvestmentJS(s.params);state.meta.calcTab='advanced';save();closeModal();render()}
function duplicateScenario(id){const raw=data.scenarios.find(x=>x.id===id),s=normalizeScenario(raw),name=`${s.name} - cópia`;data.scenarios.unshift({id:uid(),name,params_json:JSON.stringify(s.params),results_json:JSON.stringify(s.results),created_at:nowIso(),updated_at:nowIso()});queueChange('scenario',`Cenário duplicado: ${name}`);closeModal();render()}
function deleteScenarioMobile(id){const raw=data.scenarios.find(x=>x.id===id);if(!raw||!confirm(`Excluir o cenário “${raw.name}”?`))return;data.desktopExtra.deletedScenarioNames??=[];if(!data.desktopExtra.deletedScenarioNames.includes(raw.name))data.desktopExtra.deletedScenarioNames.push(raw.name);data.scenarios=data.scenarios.filter(x=>x.id!==id);queueChange('scenario_deleted',`Cenário excluído: ${raw.name}`);closeModal();render()}
function openScenarioCompare(){const ss=(data.scenarios||[]).map(normalizeScenario).slice(0,8);openModal(`<div class="sheet-handle"></div><div class="sheet-title">Comparar cenários</div><div class="sheet-sub">Até 8 cenários salvos.</div>${ss.map(s=>`<div class="card soft-card"><div class="goal-name">${escapeHtml(s.name)}</div>${infoRows([['Líquido',fmt(s.results.net||simulateInvestmentJS(s.params).net)],['Real',fmt(s.results.real_net||simulateInvestmentJS(s.params).real_net)],['Aporte',fmt(s.params.monthly||0)],['Prazo',`${s.params.years||0} anos`],['Taxa',pct(s.params.rate||0)]])}</div>`).join('')||'<div class="empty">Sem cenários para comparar.</div>'}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function bindCalculator(){}

// ---------------- METAS & RESERVA ----------------
function goalStatus(g){if(Number(g.current||0)>=Number(g.target||0)&&Number(g.target||0)>0)return 'Concluída';if(g.deadline&&String(g.deadline)<isoToday())return 'Atrasada';return 'Em andamento'}
function filteredGoals(){const f=getFilters('goals'),q=searchValue('goals');return (data.goals||[]).filter(g=>{const st=goalStatus(g);if(f.status!=='Todos'&&st!==f.status)return false;if(f.type!=='Todos'&&String(g.type||'Meta')!==f.type)return false;if(f.priority!=='Todos'&&String(g.priority||3)!==String(f.priority))return false;if(f.deadline==='Com prazo'&&!g.deadline)return false;if(f.deadline==='Sem prazo'&&g.deadline)return false;if(f.deadline==='Vencidas'&&!(g.deadline&&g.deadline<isoToday()&&st!=='Concluída'))return false;return matchSearch(g,q)}).sort((a,b)=>Number(a.priority||3)-Number(b.priority||3)||String(a.deadline||'9999').localeCompare(String(b.deadline||'9999')))}
function goals(){const r=emergencyReserve(),rows=filteredGoals();return `${sectionHead('Metas & reserva','<button class="circle-add" onclick="openNewGoal()">+</button>')}${filterBar('goals')}<div class="search-row"><input id="goalSearch" class="search" placeholder="Buscar meta, tipo ou observação..." value="${escapeHtml(searchValue('goals'))}"/><button class="secondary" onclick="openReserve()">Reserva</button></div><div class="card"><div class="row-between"><div><div class="section-title">Reserva de emergência</div><div class="muted small">Base média essencial ${fmt(r.monthly_base)} • ${r.months} meses</div></div><span class="chip ${r.progress>=100?'green':'blue'}">${pct(r.progress)}</span></div><div class="detail-kpis" style="margin-top:10px"><div class="mini-kpi"><small>Atual</small><strong>${fmt(r.current)}</strong></div><div class="mini-kpi"><small>Meta</small><strong>${fmt(r.target)}</strong></div><div class="mini-kpi"><small>Falta</small><strong>${fmt(r.missing)}</strong></div></div><div class="progress" style="margin-top:10px"><div style="width:${Math.min(100,r.progress)}%"></div></div></div><div class="card"><div class="row-between"><div class="section-title">Minhas metas</div><span class="chip blue">${rows.length}</span></div>${goalCards(rows)}</div>`}
function bindGoals(){const s=$('#goalSearch');if(s)s.oninput=()=>{setSearchValue('goals',s.value);render()}}
function goalCards(list){return list.length?list.map(g=>{const p=progressPct(g),st=goalStatus(g);return `<div class="entity-card" onclick="openGoal('${g.id}')"><div class="goal-top"><div class="goal-icon">${g.icon||'🎯'}</div><div><div class="goal-name">${escapeHtml(g.name)}</div><div class="goal-money"><strong>${fmt(g.current)}</strong> de ${fmt(g.target)} • ${escapeHtml(g.type||'Meta')}</div></div><span class="chip ${st==='Concluída'?'green':st==='Atrasada'?'yellow':'blue'}">${st}</span></div><div class="goal-bottom"><div class="progress"><div style="width:${Math.min(100,p)}%"></div></div><div class="pct">${p}%</div></div><div class="goal-meta"><span>Prioridade ${g.priority||3}</span><span>${g.deadline?brDate(g.deadline):'Sem prazo'}</span></div></div>`}).join(''):'<div class="empty">Nenhuma meta encontrada.</div>'}
function openNewGoal(){openGoalForm('')}
function goalFormHtml(g={}){return `<label>Nome</label><input id="gfName" class="field" value="${escapeHtml(g.name||'')}"/><label>Tipo</label><select id="gfType" class="field">${['Meta','Compra','Reserva','Viagem','Casa','Veículo','Educação','Outro'].map(x=>`<option ${x===(g.type||'Meta')?'selected':''}>${x}</option>`).join('')}</select><div class="sheet-row"><div><label>Valor alvo</label><input id="gfTarget" class="field" inputmode="decimal" value="${g.target||0}"/></div><div><label>Valor atual</label><input id="gfCurrent" class="field" inputmode="decimal" value="${g.current||0}"/></div></div><label>Prazo</label><input id="gfDeadline" type="date" class="field" value="${g.deadline||''}"/><label>Prioridade (1–5)</label><input id="gfPriority" class="field" inputmode="numeric" value="${g.priority||3}"/><label>Observação</label><textarea id="gfNote" class="field" rows="3">${escapeHtml(g.note||'')}</textarea>`}
function openGoalForm(id=''){const g=id?data.goals.find(x=>x.id===id):{};openModal(`<div class="sheet-handle"></div><div class="sheet-title">${id?'Editar':'Nova'} meta</div>${goalFormHtml(g)}<div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveGoalForm('${id}')">Salvar</button></div>`)}
function saveGoalForm(id){const name=$('#gfName').value.trim();if(!name)return showToast('Informe o nome');const old=id?data.goals.find(x=>x.id===id):null,obj={id:id||uid(),name,type:$('#gfType').value,target:Math.max(0,num($('#gfTarget').value)),current:Math.max(0,num($('#gfCurrent').value)),deadline:$('#gfDeadline').value,priority:clamp(parseInt($('#gfPriority').value||3),1,5),note:$('#gfNote').value.trim(),icon:old?.icon||'🎯',history:old?.history||[]};if(id)Object.assign(old,obj);else data.goals.unshift(obj);queueChange('goal',`${id?'Meta atualizada':'Meta criada'}: ${name}`);closeModal();render()}
function openGoal(id){currentRoute='goaldetail';location.hash=`#/goaldetail/${id}`;render()}
function goalDetail(){const id=location.hash.split('/')[2],g=data.goals.find(x=>x.id===id);if(!g)return `${sectionHead('Meta',backButton('goals'))}<div class="empty">Meta não encontrada.</div>`;const p=progressPct(g),st=goalStatus(g);return `${sectionHead('Detalhe da meta',backButton('goals'))}<div class="card"><div class="goal-top"><div class="goal-icon">${g.icon||'🎯'}</div><div><div class="goal-name">${escapeHtml(g.name)}</div><div class="tx-sub">${escapeHtml(g.type||'Meta')} • prioridade ${g.priority||3}</div></div><span class="chip ${st==='Concluída'?'green':st==='Atrasada'?'yellow':'blue'}">${st}</span></div><div class="detail-kpis" style="margin-top:14px"><div class="mini-kpi"><small>Alvo</small><strong>${fmt(g.target)}</strong></div><div class="mini-kpi"><small>Guardado</small><strong>${fmt(g.current)}</strong></div><div class="mini-kpi"><small>Falta</small><strong>${fmt(Math.max(0,g.target-g.current))}</strong></div></div><div class="progress" style="margin-top:12px"><div style="width:${Math.min(100,p)}%"></div></div>${g.note?`<div class="muted small" style="margin-top:10px">${escapeHtml(g.note)}</div>`:''}<div class="actions-row" style="margin-top:12px"><button class="secondary" onclick="openGoalForm('${g.id}')">Editar</button><button class="secondary" onclick="openGoalContribution('${g.id}')">Adicionar valor</button><button class="secondary" onclick="openGoalBalance('${g.id}')">Ajustar saldo</button></div></div><div class="card"><div class="row-between"><div class="section-title">Histórico de aportes</div><span class="chip blue">${(g.history||[]).length}</span></div>${(g.history||[]).map(h=>`<div class="tx"><div class="tx-icon">↗</div><div><div class="tx-title">${escapeHtml(h.note||'Aporte')}</div><div class="tx-sub">${brDate(h.date)}</div></div><div class="tx-amount income">+ ${fmt(h.amount)}</div></div>`).join('')||'<div class="empty">Nenhum aporte registrado.</div>'}</div><button class="secondary danger full-btn" onclick="deleteGoal('${g.id}')">Excluir meta</button>`}
function openGoalContribution(id){const g=data.goals.find(x=>x.id===id);openModal(`<div class="sheet-handle"></div><div class="sheet-title">Adicionar valor à meta</div><div class="sheet-sub">${escapeHtml(g.name)} • ${fmt(g.current)} de ${fmt(g.target)}</div><label>Valor</label><input id="gcAmount" class="field money-field" inputmode="decimal" value="0"/><label>Data</label><input id="gcDate" type="date" class="field" value="${isoToday()}"/><label>Observação</label><textarea id="gcNote" class="field" rows="3"></textarea><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveGoalContribution('${id}')">Registrar</button></div>`)}
function saveGoalContribution(id){const g=data.goals.find(x=>x.id===id),v=Math.max(0,num($('#gcAmount').value));if(!v)return showToast('Informe um valor');g.current=Number(g.current||0)+v;g.history??=[];g.history.unshift({id:uid(),date:$('#gcDate').value||isoToday(),amount:v,note:$('#gcNote').value.trim(),createdAt:nowIso()});queueChange('goal_contribution',`${g.name}: +${fmt(v)}`);closeModal();render()}
function openGoalBalance(id){const g=data.goals.find(x=>x.id===id);openModal(`<div class="sheet-handle"></div><div class="sheet-title">Ajustar saldo</div><div class="sheet-sub">Use para conciliar o valor real da meta sem criar um aporte fictício.</div><label>Novo valor guardado</label><input id="gbValue" class="field money-field" inputmode="decimal" value="${g.current||0}"/><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveGoalBalance('${id}')">Ajustar</button></div>`)}
function saveGoalBalance(id){const g=data.goals.find(x=>x.id===id),before=Number(g.current||0),after=Math.max(0,num($('#gbValue').value));g.current=after;queueChange('goal_balance',`${g.name}: saldo ${fmt(before)} → ${fmt(after)}`);closeModal();render()}
function openReserve(){const r=emergencyReserve();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Reserva de emergência</div>${infoRows([['Base essencial média',fmt(r.monthly_base)],['Meta atual',fmt(r.target)],['Falta',fmt(r.missing)]])}<label>Valor atualmente reservado</label><input id="rvCurrent" class="field money-field" inputmode="decimal" value="${r.current}"/><label>Meses de cobertura</label><input id="rvMonths" class="field" inputmode="numeric" value="${r.months}"/><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveReserve()">Salvar</button></div>`)}
function saveReserve(){data.reserve.current=Math.max(0,num($('#rvCurrent').value));data.reserve.months=clamp(parseInt($('#rvMonths').value||6),1,60);queueChange('reserve','Reserva de emergência atualizada');closeModal();render()}
function deleteGoal(id){const g=data.goals.find(x=>x.id===id);if(g&&confirm(`Excluir a meta “${g.name}”?`)){data.goals=data.goals.filter(x=>x.id!==id);queueChange('goal_deleted',`Meta ${g.name} excluída`);if(location.hash)history.replaceState(null,'',' ');nav('goals')}}

// ---------------- PATRIMÔNIO / CONTAS ----------------
function filteredAccounts(){const f=getFilters('networth'),q=searchValue('networth');return (data.accounts||[]).filter(a=>{if(f.institution!=='Todos'&&String(a.institution||'')!==f.institution)return false;if(f.type!=='Todos'&&String(a.type||'')!==f.type)return false;if(f.include!=='Todos'&&(boolish(a.include,true)!==(f.include==='Sim')))return false;return matchSearch(a,q)})}
function networth(){const n=networthSummary(),rows=filteredAccounts();return `${sectionHead('Patrimônio','<button class="circle-add" onclick="openAccountForm()">+</button>')}${filterBar('networth')}<div class="search-row"><input id="accountSearch" class="search" placeholder="Buscar conta, instituição ou tipo..." value="${escapeHtml(searchValue('networth'))}"/><button class="secondary" onclick="openReconciliationHistory()">Conciliações</button></div><div class="kpi-grid-2">${kpiHtml('Patrimônio líquido',fmt(n.networth),'Contas + investimentos − dívidas','green')}${kpiHtml('Contas',fmt(n.accounts),`${rows.length} conta(s)`,'')}${kpiHtml('Investimentos',fmt(n.investments),'Valor de mercado','purple')}${kpiHtml('Dívidas',fmt(n.debts),'Saldo devedor','red')}</div><div class="card">${appCardTitle('Composição')}${simpleBars([['Contas',n.accounts],['Investimentos',n.investments],['Reserva ref.',n.reserve_reference],['Dívidas',n.debts]],8)}</div><div class="card"><div class="row-between"><div class="section-title">Contas e saldos</div><span class="chip blue">${rows.length}</span></div>${rows.map(a=>`<div class="entity-card" onclick="openAccountActions('${a.id}')"><div class="row-between"><div><div class="goal-name">${escapeHtml(a.name)}</div><div class="tx-sub">${escapeHtml(a.institution||'')} • ${escapeHtml(a.type||'Conta')}</div></div><strong>${fmt(a.balance)}</strong></div><div class="goal-meta"><span>${boolish(a.include,true)?'Inclui no patrimônio':'Fora do patrimônio'}</span><span>Base ${a.openingDate?brDate(a.openingDate):'não definida'}</span></div></div>`).join('')||'<div class="empty">Nenhuma conta encontrada.</div>'}</div>`}
function bindAccountSearch(){const s=$('#accountSearch');if(s)s.oninput=()=>{setSearchValue('networth',s.value);render()}}
function accountFormHtml(a={}){return `<label>Nome da conta</label><input id="acName" class="field" value="${escapeHtml(a.name||'')}"/><label>Instituição</label><input id="acInstitution" class="field" value="${escapeHtml(a.institution||'')}"/><label>Tipo</label><select id="acType" class="field">${['Conta corrente','Conta digital','Poupança','Dinheiro','Corretora','Outro'].map(x=>`<option ${x===(a.type||'Conta corrente')?'selected':''}>${x}</option>`).join('')}</select><label>Saldo informado</label><input id="acBalance" class="field money-field" inputmode="decimal" value="${a.balance||0}"/><label>Incluir no patrimônio?</label><select id="acInclude" class="field"><option value="1" ${boolish(a.include,true)?'selected':''}>Sim</option><option value="0" ${!boolish(a.include,true)?'selected':''}>Não</option></select><label>Observação</label><textarea id="acNotes" class="field" rows="3">${escapeHtml(a.notes||'')}</textarea>`}
function openAccountForm(id=''){const a=id?data.accounts.find(x=>x.id===id):{};openModal(`<div class="sheet-handle"></div><div class="sheet-title">${id?'Editar':'Nova'} conta</div>${accountFormHtml(a)}<div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveAccountForm('${id}')">Salvar</button></div>`)}
function saveAccountForm(id){const name=$('#acName').value.trim();if(!name)return showToast('Informe o nome da conta');const old=id?data.accounts.find(x=>x.id===id):null,oldName=old?.name||'',balance=num($('#acBalance').value),obj={id:id||uid(),name,institution:$('#acInstitution').value.trim(),type:$('#acType').value,balance,openingBalance:old?.openingBalance??balance,openingDate:old?.openingDate||isoToday(),include:$('#acInclude').value==='1',active:true,icon:old?.icon||'💳',notes:$('#acNotes').value.trim()};if(id){Object.assign(old,obj);if(oldName&&oldName!==name){(data.transactions||[]).forEach(t=>{if(t.account===oldName)t.account=name});(data.recurring||[]).forEach(r=>{if(r.account===oldName)r.account=name});(data.desktopExtra.reconciliations||[]).forEach(r=>{if(r.account===oldName)r.account=name})}}else data.accounts.unshift(obj);queueChange('account',`${id?'Conta atualizada':'Conta criada'}: ${name}`);closeModal();render()}
function openAccountActions(id){const a=data.accounts.find(x=>x.id===id);if(!a)return;openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(a.name)}</div><div class="sheet-sub">${escapeHtml(a.institution||'')} • saldo ${fmt(a.balance)}</div><div class="action-list"><button class="secondary" onclick="openAccountForm('${id}')">Editar cadastro</button><button class="secondary" onclick="openAccountBalance('${id}')">Atualizar saldo</button><button class="secondary" onclick="openReconciliation('${id}')">Conciliar conta</button><button class="secondary" onclick="openReconciliationHistory('${a.name.replace(/'/g,"\\'")}')">Histórico de conciliações</button><button class="secondary danger" onclick="deleteAccount('${id}')">Excluir conta</button></div><div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function openAccountBalance(id){const a=data.accounts.find(x=>x.id===id);closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Atualizar saldo</div><div class="sheet-sub">Ao atualizar, esta data vira a nova âncora para a conciliação.</div><label>Novo saldo</label><input id="abValue" class="field money-field" inputmode="decimal" value="${a.balance}"/><label>Data de referência</label><input id="abDate" type="date" class="field" value="${isoToday()}"/><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveAccountBalance('${id}')">Atualizar</button></div>`)}
function saveAccountBalance(id){const a=data.accounts.find(x=>x.id===id),v=num($('#abValue').value),dt=$('#abDate').value||isoToday();a.balance=v;a.openingBalance=v;a.openingDate=dt;queueChange('account_balance',`${a.name}: saldo atualizado`);closeModal();render()}
function openReconciliation(id){const a=data.accounts.find(x=>x.id===id),ref=isoToday(),calc=calculatedAccountBalance(a.name,ref);closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Conciliar conta</div><div class="sheet-sub">Compare o saldo calculado pelas movimentações com o saldo real informado.</div><label>Data de referência</label><input id="rcDate" type="date" class="field" value="${ref}" onchange="updateReconciliationCalc('${id}')"/><label>Saldo informado</label><input id="rcInformed" class="field money-field" inputmode="decimal" value="${a.balance}" oninput="updateReconciliationCalc('${id}')"/><div id="rcCalc">${reconciliationCalcHtml(calc,a.balance)}</div><label>Observação</label><textarea id="rcNotes" class="field" rows="3"></textarea><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveReconciliation('${id}')">Salvar conciliação</button></div>`)}
function reconciliationCalcHtml(calc,informed){const diff=Number(informed||0)-Number(calc||0);return `<div class="card soft-card">${infoRows([['Saldo calculado',fmt(calc)],['Saldo informado',fmt(informed)],['Diferença',`<span class="${Math.abs(diff)<.01?'income':'expense'}">${fmt(diff)}</span>`]])}</div>`}
function updateReconciliationCalc(id){const a=data.accounts.find(x=>x.id===id),ref=$('#rcDate').value,calc=calculatedAccountBalance(a.name,ref),inf=num($('#rcInformed').value);$('#rcCalc').innerHTML=reconciliationCalcHtml(calc,inf)}
function saveReconciliation(id){const a=data.accounts.find(x=>x.id===id),ref=$('#rcDate').value||isoToday(),calc=calculatedAccountBalance(a.name,ref),inf=num($('#rcInformed').value),diff=Math.round((inf-calc)*100)/100,rec={id:uid(),account:a.name,reference_date:ref,informed_balance:inf,calculated_balance:calc,difference:diff,notes:$('#rcNotes').value.trim(),created_at:nowIso()};data.desktopExtra.reconciliations??=[];data.desktopExtra.reconciliations.unshift(rec);a.balance=inf;a.openingBalance=inf;a.openingDate=ref;queueChange('reconciliation',`${a.name}: diferença ${fmt(diff)}`);closeModal();render()}
function openReconciliationHistory(account=''){const rows=(data.desktopExtra.reconciliations||[]).filter(r=>!account||r.account===account).sort((a,b)=>String(b.reference_date||'').localeCompare(String(a.reference_date||''))).slice(0,150);openModal(`<div class="sheet-handle"></div><div class="sheet-title">Histórico de conciliações</div>${rows.map(r=>`<div class="tx"><div class="tx-icon">≈</div><div><div class="tx-title">${escapeHtml(r.account||'Conta')}</div><div class="tx-sub">${brDate(r.reference_date)} • ${escapeHtml(r.notes||'')}</div></div><div><div class="tx-amount ${Math.abs(Number(r.difference||0))<.01?'income':'expense'}">${fmt(r.difference)}</div><div class="tx-time">Real ${fmt(r.informed_balance)}</div></div></div>`).join('')||'<div class="empty">Nenhuma conciliação.</div>'}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function deleteAccount(id){const a=data.accounts.find(x=>x.id===id);if(a&&confirm(`Excluir a conta “${a.name}”?`)){data.accounts=data.accounts.filter(x=>x.id!==id);queueChange('account_deleted',`Conta ${a.name} excluída`);closeModal();render()}}

// ---------------- CARTÕES E PARCELAS ----------------
function cardProjection(){const out={};for(const i of data.installments||[]){if(boolish(i.paid,false))continue;const ym=String(i.dueDate||'').slice(0,7);if(/^\d{4}-\d{2}$/.test(ym))out[ym]=(out[ym]||0)+Number(i.amount||0)}return out}
function filteredCards(){const f=getFilters('cards'),q=searchValue('cards');return (data.cards||[]).filter(c=>{if(f.bank!=='Todos'&&String(c.bank||'')!==f.bank)return false;if(f.card!=='Todos'&&String(c.name||'')!==f.card)return false;return matchSearch(c,q)})}
function filteredInstallments(){const f=getFilters('cards'),q=searchValue('cards'),today=isoToday();return (data.installments||[]).filter(i=>{const card=data.cards.find(c=>c.id===i.cardId);if(f.bank!=='Todos'&&String(card?.bank||'')!==f.bank)return false;if(f.card!=='Todos'&&String(i.cardName||card?.name||'')!==f.card)return false;if(f.year!=='Todos'&&String(i.dueDate||'').slice(0,4)!==String(f.year))return false;if(Number(f.month)>0&&Number(String(i.dueDate||'').slice(5,7))!==Number(f.month))return false;const st=boolish(i.paid)?'Pago':String(i.dueDate)<today?'Vencido':'Aberto';if(f.installmentStatus!=='Todos'&&st!==f.installmentStatus)return false;return matchSearch({...i,cardName:i.cardName||card?.name},q)}).sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate)))}
function cards(){const rows=filteredCards(),inst=filteredInstallments(),open=(data.installments||[]).filter(x=>!boolish(x.paid)),openTotal=open.reduce((s,x)=>s+Number(x.amount||0),0),limits=(data.cards||[]).reduce((s,c)=>s+Number(c.limit||0),0),invoices=(data.cards||[]).reduce((s,c)=>s+Number(c.invoice||0),0),proj=Object.entries(cardProjection()).sort().slice(0,12);return `${sectionHead('Cartões','<button class="circle-add" onclick="openCardForm()">+</button>')}${filterBar('cards')}<div class="search-row"><input id="cardSearch" class="search" placeholder="Buscar cartão, banco ou compra..." value="${escapeHtml(searchValue('cards'))}"/><button class="secondary" onclick="openCardPurchase()">Nova compra</button></div><div class="kpi-grid-2">${kpiHtml('Limites',fmt(limits),`${data.cards.length} cartão(ões)`,'')}${kpiHtml('Faturas atuais',fmt(invoices),'Informado nos cartões','red')}${kpiHtml('Parcelas em aberto',fmt(openTotal),`${open.length} parcela(s)`,'purple')}${kpiHtml('Disponível estimado',fmt(limits-invoices),'Limite − faturas','green')}</div><div class="card">${appCardTitle('Projeção de faturas','Parcelas futuras em aberto')}${simpleBars(proj.map(([ym,v])=>[ym,v]),12)}</div><div class="card"><div class="section-title">Cartões cadastrados</div>${rows.map(c=>{const avail=Number(c.limit||0)-Number(c.invoice||0),used=Number(c.limit||0)?Number(c.invoice||0)/Number(c.limit||0)*100:0;return `<div class="entity-card" onclick="openCardActions('${c.id}')"><div class="row-between"><div><div class="goal-name">${escapeHtml(c.name)}</div><div class="tx-sub">${escapeHtml(c.bank||'')} • vence dia ${c.dueDay||'—'} • fecha dia ${c.closingDay||'—'}</div></div><strong>${fmt(c.invoice||0)}</strong></div><div class="progress ${used>=90?'yellow':'blue'}" style="margin-top:8px"><div style="width:${Math.min(100,used)}%"></div></div><div class="goal-meta"><span>Limite ${fmt(c.limit)}</span><span>Disponível ${fmt(avail)}</span></div></div>`}).join('')||'<div class="empty">Nenhum cartão encontrado.</div>'}</div><div class="card"><div class="row-between"><div class="section-title">Parcelas</div><span class="chip blue">${inst.length}</span></div>${inst.slice(0,250).map(i=>{const st=boolish(i.paid)?'Pago':String(i.dueDate)<isoToday()?'Vencido':'Aberto';return `<div class="tx" onclick="openInstallmentActions('${i.id}')"><div class="tx-icon">▣</div><div><div class="tx-title">${escapeHtml(i.description||'Compra')} • ${i.installmentNo||1}/${i.installments||1}</div><div class="tx-sub">${escapeHtml(i.cardName||'Cartão')} • ${brDate(i.dueDate)}</div></div><div><div class="tx-amount">${fmt(i.amount)}</div><div class="tx-time"><span class="chip ${st==='Pago'?'green':st==='Vencido'?'yellow':'blue'}">${st}</span></div></div></div>`}).join('')||'<div class="empty">Nenhuma parcela encontrada.</div>'}</div>`}
function bindCardSearch(){const s=$('#cardSearch');if(s)s.oninput=()=>{setSearchValue('cards',s.value);render()}}
function cardFormHtml(c={}){return `<label>Cartão</label><input id="cfName" class="field" value="${escapeHtml(c.name||'')}"/><label>Banco</label><input id="cfBank" class="field" value="${escapeHtml(c.bank||'')}"/><div class="sheet-row"><div><label>Limite</label><input id="cfLimit" class="field" inputmode="decimal" value="${c.limit||0}"/></div><div><label>Fatura atual</label><input id="cfInvoice" class="field" inputmode="decimal" value="${c.invoice||0}"/></div></div><div class="sheet-row"><div><label>Fecha dia</label><input id="cfClose" class="field" inputmode="numeric" value="${c.closingDay||0}"/></div><div><label>Vence dia</label><input id="cfDue" class="field" inputmode="numeric" value="${c.dueDay||0}"/></div></div><label>Observação</label><textarea id="cfNotes" class="field" rows="3">${escapeHtml(c.notes||'')}</textarea>`}
function openCardForm(id=''){const c=id?data.cards.find(x=>x.id===id):{};openModal(`<div class="sheet-handle"></div><div class="sheet-title">${id?'Editar':'Novo'} cartão</div>${cardFormHtml(c)}<div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveCardForm('${id}')">Salvar</button></div>`)}
function saveCardForm(id){const name=$('#cfName').value.trim();if(!name)return showToast('Informe o cartão');const old=id?data.cards.find(x=>x.id===id):null,obj={id:id||uid(),name,bank:$('#cfBank').value.trim(),limit:Math.max(0,num($('#cfLimit').value)),invoice:Math.max(0,num($('#cfInvoice').value)),closingDay:clamp(parseInt($('#cfClose').value||0),0,31),dueDay:clamp(parseInt($('#cfDue').value||0),0,31),notes:$('#cfNotes').value.trim()};if(id){const oldName=old.name;Object.assign(old,obj);(data.installments||[]).forEach(i=>{if(i.cardId===id)i.cardName=name});if(oldName!==name)queueChange('card_rename',`${oldName} → ${name}`)}else data.cards.unshift(obj);queueChange('card',`${id?'Cartão atualizado':'Cartão criado'}: ${name}`);closeModal();render()}
function openCardActions(id){const c=data.cards.find(x=>x.id===id);openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(c.name)}</div><div class="sheet-sub">${escapeHtml(c.bank||'')} • limite ${fmt(c.limit)} • fatura ${fmt(c.invoice)}</div><div class="action-list"><button class="secondary" onclick="openCardForm('${id}')">Editar cartão</button><button class="secondary" onclick="openCardPurchase('${id}')">Nova compra parcelada</button><button class="secondary" onclick="openCardPurchaseHistory('${id}')">Compras e parcelas</button><button class="secondary danger" onclick="deleteCardMobile('${id}')">Excluir cartão</button></div><div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function openCardPurchase(cardId=''){if(!(data.cards||[]).length)return showToast('Cadastre um cartão primeiro');closeModal();const c=cardId||data.cards[0].id,first=isoToday();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Nova compra parcelada</div><label>Cartão</label><select id="cpCard" class="field">${data.cards.map(x=>`<option value="${x.id}" ${x.id===c?'selected':''}>${escapeHtml(x.name)} • ${escapeHtml(x.bank||'')}</option>`).join('')}</select><label>Data da compra</label><input id="cpDate" type="date" class="field" value="${isoToday()}"/><label>Descrição</label><input id="cpDesc" class="field"/><label>Valor total</label><input id="cpTotal" class="field money-field" inputmode="decimal" value="0"/><label>Número de parcelas</label><input id="cpN" class="field" inputmode="numeric" value="1"/><label>Primeiro vencimento</label><input id="cpFirst" type="date" class="field" value="${first}"/><label>Observação</label><textarea id="cpNotes" class="field" rows="3"></textarea><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveCardPurchase()">Salvar compra</button></div>`)}
function splitInstallmentsCents(total,n){const cents=Math.round(Math.max(0,total)*100),base=Math.floor(cents/n),rem=cents-base*n;return Array.from({length:n},(_,i)=>(base+(i<rem?1:0))/100)}
function saveCardPurchase(){const card=data.cards.find(x=>x.id===$('#cpCard').value),desc=$('#cpDesc').value.trim(),total=Math.max(0,num($('#cpTotal').value)),n=clamp(parseInt($('#cpN').value||1),1,240),first=$('#cpFirst').value;if(!card||!desc||!total||!first)return showToast('Preencha cartão, descrição, valor e vencimento');const purchase={id:uid(),cardId:card.id,purchaseDate:$('#cpDate').value||isoToday(),description:desc,total,installments:n,firstDueDate:first,notes:$('#cpNotes').value.trim(),createdAt:nowIso()};data.cardPurchases??=[];data.cardPurchases.unshift(purchase);const values=splitInstallmentsCents(total,n);data.installments??=[];values.forEach((amount,i)=>data.installments.push({id:uid(),purchaseId:purchase.id,cardId:card.id,cardName:card.name,installmentNo:i+1,dueDate:addMonthsIso(first,i),amount,paid:false,paidAt:'',description:desc,installments:n}));queueChange('card_purchase',`${card.name}: ${desc} ${fmt(total)} em ${n}x`);closeModal();render()}
function openInstallmentActions(id){const i=data.installments.find(x=>x.id===id),p=(data.cardPurchases||[]).find(x=>x.id===i.purchaseId);openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(i.description||'Parcela')}</div>${infoRows([['Cartão',escapeHtml(i.cardName||'')],['Parcela',`${i.installmentNo}/${i.installments}`],['Vencimento',brDate(i.dueDate)],['Valor',fmt(i.amount)],['Status',boolish(i.paid)?'Pago':'Aberto'],['Compra total',p?fmt(p.total):'—']])}<div class="action-list"><button class="secondary" onclick="toggleInstallmentPaid('${id}')">${boolish(i.paid)?'Marcar como aberta':'Marcar como paga'}</button>${p?`<button class="secondary" onclick="openPurchaseDetails('${p.id}')">Ver compra completa</button>`:''}</div><div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function toggleInstallmentPaid(id){const i=data.installments.find(x=>x.id===id);i.paid=!boolish(i.paid);i.paidAt=i.paid?nowIso():'';queueChange('card_installment',`${i.description}: parcela ${i.installmentNo} ${i.paid?'paga':'reaberta'}`);closeModal();render()}
function openPurchaseDetails(id){const p=(data.cardPurchases||[]).find(x=>x.id===id),rows=(data.installments||[]).filter(x=>x.purchaseId===id).sort((a,b)=>a.installmentNo-b.installmentNo);closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(p.description)}</div>${infoRows([['Data',brDate(p.purchaseDate)],['Total',fmt(p.total)],['Parcelas',String(p.installments)],['Primeiro vencimento',brDate(p.firstDueDate)],['Observação',escapeHtml(p.notes||'—')]])}${rows.map(i=>`<div class="info-row"><span>${i.installmentNo}/${i.installments} • ${brDate(i.dueDate)}</span><strong class="${i.paid?'income':''}">${fmt(i.amount)} ${i.paid?'✓':''}</strong></div>`).join('')}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function openCardPurchaseHistory(cardId){const rows=(data.cardPurchases||[]).filter(p=>p.cardId===cardId).sort((a,b)=>String(b.purchaseDate).localeCompare(String(a.purchaseDate)));closeModal();openModal(`<div class="sheet-handle"></div><div class="sheet-title">Compras do cartão</div>${rows.map(p=>`<div class="tx" onclick="openPurchaseDetails('${p.id}')"><div class="tx-icon">▣</div><div><div class="tx-title">${escapeHtml(p.description)}</div><div class="tx-sub">${brDate(p.purchaseDate)} • ${p.installments}x</div></div><strong>${fmt(p.total)}</strong></div>`).join('')||'<div class="empty">Nenhuma compra cadastrada.</div>'}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function deleteCardMobile(id){const c=data.cards.find(x=>x.id===id);if(c&&confirm(`Excluir o cartão “${c.name}”? As compras e parcelas permanecem no histórico, como no PC.`)){data.cards=data.cards.filter(x=>x.id!==id);queueChange('card_deleted',`Cartão ${c.name} excluído`);closeModal();render()}}

// ---------------- SAÚDE FINANCEIRA ----------------
function health(){const h=financialHealth();return `${sectionHead('Saúde financeira','')}<div class="kpi-grid-2">${kpiHtml('Score financeiro',`${Math.round(h.score)}/100`,'Leitura combinada',h.score>=75?'green':h.score<50?'red':'')}${kpiHtml('Taxa de poupança',pct(h.savings_rate),`Renda média ${fmt(h.avg_income)}`,'')}${kpiHtml('Dívidas / renda',pct(h.debt_commitment),'Comprometimento mensal',h.debt_commitment>30?'red':'')}${kpiHtml('Reserva',`${h.reserve_months.toFixed(1).replace('.',',')} meses`,'Cobertura de gastos essenciais','green')}${kpiHtml('Essenciais / renda',pct(h.essential_pct),'Média dos últimos meses','')}${kpiHtml('Patrimônio líquido',fmt(h.networth),`Período ${h.period}`,'purple')}</div><div class="card"><div class="section-title">Alertas e leitura automática</div>${h.alerts.map(([level,text])=>`<div class="alert-row"><span class="chip ${['Crítico','Atenção'].includes(level)?'yellow':level==='Bom'?'green':'blue'}">${escapeHtml(level)}</span><div>${escapeHtml(text)}</div></div>`).join('')}</div><div class="card">${appCardTitle('Base usada no cálculo','Média recente de até 6 meses')}${infoRows([['Renda média',fmt(h.avg_income)],['Gasto médio',fmt(h.avg_expense)],['Taxa de poupança',pct(h.savings_rate)],['Comprometimento de dívidas',pct(h.debt_commitment)],['Cobertura da reserva',`${h.reserve_months.toFixed(2).replace('.',',')} meses`],['Gastos essenciais',pct(h.essential_pct)]])}</div>`}

// ---------------- RELATÓRIOS ----------------
function reports(){const f=getFilters('reports'),year=Number(f.year)||latestPeriod().year,month=Number(f.month)||0,r=month?periodMetrics(year,month):annualReport(year),series=monthlySeries(year),top=topDescriptions(year,month,15),cats=month?Object.entries(r.categories||{}):Object.entries(Array.from({length:12},(_,i)=>periodMetrics(year,i+1).categories).reduce((acc,o)=>{for(const [k,v] of Object.entries(o))acc[k]=(acc[k]||0)+v;return acc},{})).sort((a,b)=>b[1]-a[1]),income=r.income,expense=r.expense,balance=r.balance,investments=r.investments||periodMetrics(year,month).investments;return `${sectionHead('Relatórios','<button class="secondary" onclick="exportReportCsv()">Exportar CSV</button>')}${filterBar('reports')}<div class="kpi-grid-2">${kpiHtml('Receitas',fmt(income),month?`${monthName(month)}/${year}`:`Ano ${year}`,'green')}${kpiHtml('Gastos',fmt(expense),'Total consolidado','red')}${kpiHtml('Saldo',fmt(balance),'Receitas − gastos',balance>=0?'green':'red')}${kpiHtml('Aportes',fmt(investments),'Investimentos identificados','purple')}</div><div class="card">${appCardTitle('Fluxo mensal',String(year))}${monthlyBars(series)}</div><div class="card">${appCardTitle('Maiores descrições de gasto',month?`${monthName(month)}/${year}`:String(year))}${simpleBars(top,15)}</div><div class="card">${appCardTitle('Gastos por categoria')}${simpleBars(cats,15)}</div>`}
function exportReportCsv(){const f=getFilters('reports'),y=Number(f.year)||latestPeriod().year,m=Number(f.month)||0,rows=(data.transactions||[]).filter(x=>inPeriod(x,y,m));const head='Data;Descrição;Categoria;Conta;Tipo;Valor;Impacta orçamento;Transferência própria;Observação\n',body=rows.map(x=>[x.date,x.description,x.category,x.account,x.type,x.amount,boolish(x.impactBudget,true)?'Sim':'Não',boolish(x.ownTransfer)?'Sim':'Não',x.notes].map(csvEscape).join(';')).join('\n');downloadText(`relatorio_${y}_${m||'ano'}.csv`,head+body,'text/csv;charset=utf-8');showToast('Relatório exportado')}

// ---------------- IMPORTAÇÃO NUBANK ----------------
function filteredImportHistory(){const f=getFilters('imports');return (data.importedFiles||[]).filter(x=>f.status==='Todos'||String(x.status||'Concluído')===f.status).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
function importPage(){const rows=filteredImportHistory();return `${sectionHead('Importar Nubank','<button class="secondary" onclick="nav(\'rules\')">Regras</button>')}${filterBar('imports')}<div class="card"><div class="section-title">Importar arquivo CSV</div><div class="muted small">Pré-visualiza, aplica as mesmas regras de classificação do PC e detecta duplicidades antes de gravar.</div><input id="nubankFile" type="file" accept=".csv,text/csv" class="field" style="margin-top:12px"/><button class="primary" onclick="previewNubank()">Ler e validar arquivo</button></div><div id="importPreview"></div><div class="card"><div class="row-between"><div class="section-title">Histórico de importações</div><span class="chip blue">${rows.length}</span></div>${rows.map(x=>`<div class="entity-card" onclick="openImportDetails('${x.id}')"><div class="row-between"><div><div class="goal-name">${escapeHtml(x.name)}</div><div class="tx-sub">${x.date?String(x.date).replace('T',' '):''} • ${escapeHtml(x.status||'Concluído')}</div></div><strong>${Number(x.rows||0)} novas</strong></div><div class="goal-meta"><span>Lidas ${Number(x.rowsRead??x.rows??0)} • duplicadas ${Number(x.duplicates||0)}</span><span>Erros ${Number(x.errors||0)}</span></div></div>`).join('')||'<div class="empty">Nenhum arquivo importado.</div>'}</div><div class="card">${appCardTitle('Classificação automática',`${(data.desktopExtra.rules||[]).length} regra(s) sincronizada(s) do PC`)}<button class="secondary full-btn" onclick="nav('rules')">Gerenciar regras</button></div>`}
function openImportDetails(id){const x=(data.importedFiles||[]).find(r=>String(r.id)===String(id));if(!x)return;openModal(`<div class="sheet-handle"></div><div class="sheet-title">${escapeHtml(x.name)}</div>${infoRows([['Importado em',escapeHtml(String(x.date||'').replace('T',' '))],['Status',escapeHtml(x.status||'Concluído')],['Linhas lidas',String(x.rowsRead??x.rows??0)],['Adicionadas',String(x.rows||0)],['Duplicadas',String(x.duplicates||0)],['Erros',String(x.errors||0)],['Entradas',fmt(x.totalIn||0)],['Saídas',fmt(x.totalOut||0)],['Hash',escapeHtml(x.hash||'—')]])}<div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}

// ---------------- CATEGORIAS ----------------
function categoriesPage(){const rows=categoryRows(false);return `${sectionHead('Categorias','<button class="circle-add" onclick="openCategoryForm()">+</button>')}<div class="card"><div class="muted small">As categorias são compartilhadas com o PC e usadas em orçamento, relatórios e classificação.</div>${rows.map(c=>`<div class="entity-card" onclick="openCategoryForm('${encodeURIComponent(c.name)}')"><div class="row-between"><div><div class="goal-name">${escapeHtml(c.name)}</div><div class="tx-sub">Grupo ${escapeHtml(c.group_name||'Outros')} • ${boolish(c.essential)?'Essencial':'Não essencial'}</div></div><span class="chip ${boolish(c.active,true)?'green':'yellow'}">${boolish(c.active,true)?'Ativa':'Inativa'}</span></div></div>`).join('')||'<div class="empty">Nenhuma categoria.</div>'}</div>`}
function openCategoryForm(encoded=''){const name=encoded?decodeURIComponent(encoded):'',c=categoryRows(false).find(x=>x.name===name)||{};openModal(`<div class="sheet-handle"></div><div class="sheet-title">${name?'Editar':'Nova'} categoria</div><label>Nome</label><input id="ctName" class="field" value="${escapeHtml(c.name||'')}" ${name?'readonly':''}/><label>Grupo</label><select id="ctGroup" class="field">${['Receita','Despesa','Investimento','Neutro','Outros'].map(x=>`<option ${x===(c.group_name||'Despesa')?'selected':''}>${x}</option>`).join('')}</select><label>Essencial?</label><select id="ctEssential" class="field"><option value="1" ${boolish(c.essential)?'selected':''}>Sim</option><option value="0" ${!boolish(c.essential)?'selected':''}>Não</option></select><label>Ativa?</label><select id="ctActive" class="field"><option value="1" ${boolish(c.active,true)?'selected':''}>Sim</option><option value="0" ${!boolish(c.active,true)?'selected':''}>Não</option></select><div class="sheet-footer"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveCategoryForm('${encodeURIComponent(name)}')">Salvar</button></div>`)}
function saveCategoryForm(oldEncoded){const oldName=decodeURIComponent(oldEncoded||''),typed=$('#ctName').value.trim(),name=oldName||typed;if(!name)return showToast('Informe o nome');let r=data.desktopExtra.categories.find(x=>x.name===oldName);const obj={...(r||{}),id:r?.id||uid(),name,group_name:$('#ctGroup').value,essential:$('#ctEssential').value==='1'?1:0,active:$('#ctActive').value==='1'?1:0};if(r)Object.assign(r,obj);else data.desktopExtra.categories.push(obj);queueChange('category',`${oldName?'Categoria atualizada':'Categoria criada'}: ${name}`);closeModal();render()}

// ---------------- REGRAS DE CLASSIFICAÇÃO ----------------
function rulesPage(){const rows=[...(data.desktopExtra.rules||[])].sort((a,b)=>Number(a.priority||100)-Number(b.priority||100));return `${sectionHead('Regras de classificação','<button class="circle-add" onclick="openRuleForm()">+</button>')}<div class="card"><div class="muted small">Padrões usados na importação Nubank e na identificação automática de movimentações.</div>${rows.map(r=>`<div class="entity-card" onclick="openRuleForm('${r.id??''}')"><div class="row-between"><div><div class="goal-name">${escapeHtml(r.pattern||'')}</div><div class="tx-sub">${escapeHtml(r.category||'Outros')} • prioridade ${r.priority||100}</div></div><span class="chip ${boolish(r.is_own_transfer)?'yellow':'blue'}">${boolish(r.is_own_transfer)?'Transferência':'Orçamento '+(boolish(r.impact_budget,true)?'Sim':'Não')}</span></div></div>`).join('')||'<div class="empty">Nenhuma regra cadastrada.</div>'}</div>`}
function openRuleForm(id=''){const r=(data.desktopExtra.rules||[]).find(x=>String(x.id)===String(id))||{};openModal(`<div class="sheet-handle"></div><div class="sheet-title">${id?'Editar':'Nova'} regra</div><label>Prioridade</label><input id="rlPriority" class="field" inputmode="numeric" value="${r.priority||50}"/><label>Texto a procurar</label><input id="rlPattern" class="field" value="${escapeHtml(r.pattern||'')}"/><label>Categoria</label><select id="rlCategory" class="field">${categoryNames(true).map(x=>`<option ${x===(r.category||'Outros')?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select><label>Impacta orçamento?</label><select id="rlImpact" class="field"><option value="1" ${boolish(r.impact_budget,true)?'selected':''}>Sim</option><option value="0" ${!boolish(r.impact_budget,true)?'selected':''}>Não</option></select><label>Transferência própria?</label><select id="rlOwn" class="field"><option value="0" ${!boolish(r.is_own_transfer)?'selected':''}>Não</option><option value="1" ${boolish(r.is_own_transfer)?'selected':''}>Sim</option></select><div class="sheet-footer stacked"><button class="secondary" onclick="closeModal()">Cancelar</button>${id?`<button class="secondary danger" onclick="deleteRuleMobile('${id}')">Excluir</button>`:''}<button class="primary" onclick="saveRuleForm('${id}')">Salvar</button></div>`)}
function saveRuleForm(id){const p=$('#rlPattern').value.trim();if(!p)return showToast('Informe o padrão');let r=data.desktopExtra.rules.find(x=>String(x.id)===String(id));const obj={id:r?.id||uid(),priority:clamp(parseInt($('#rlPriority').value||50),1,999),pattern:p,category:$('#rlCategory').value,impact_budget:$('#rlImpact').value==='1'?1:0,is_own_transfer:$('#rlOwn').value==='1'?1:0};if(r)Object.assign(r,obj);else data.desktopExtra.rules.push(obj);queueChange('rule',`${id?'Regra atualizada':'Regra criada'}: ${p}`);closeModal();render()}
function deleteRuleMobile(id){const r=data.desktopExtra.rules.find(x=>String(x.id)===String(id));if(r&&confirm(`Excluir a regra “${r.pattern}”?`)){data.desktopExtra.rules=data.desktopExtra.rules.filter(x=>String(x.id)!==String(id));queueChange('rule_deleted',`Regra ${r.pattern} excluída`);closeModal();render()}}

// ---------------- AUDITORIA, LIXEIRA E DIAGNÓSTICO ----------------
function filteredAudit(){const f=getFilters('audit'),q=searchValue('audit');return (data.desktopExtra.auditLog||[]).filter(r=>{if(f.module!=='Todos'&&String(r.table_name||'')!==f.module)return false;if(f.action!=='Todos'&&String(r.action||'')!==f.action)return false;return matchSearch(r,q)}).slice(0,500)}
function auditPage(){const rows=filteredAudit();return `${sectionHead('Histórico de alterações','')}${filterBar('audit')}<input id="auditSearch" class="search" placeholder="Buscar módulo, ação ou conteúdo..." value="${escapeHtml(searchValue('audit'))}"/><div class="card"><div class="row-between"><div class="section-title">Auditoria do desktop</div><span class="chip blue">${rows.length}</span></div>${rows.map(r=>`<div class="entity-card" onclick="openAuditDetail('${r.id}')"><div class="row-between"><div><div class="goal-name">${escapeHtml(r.action||'ALTERAÇÃO')}</div><div class="tx-sub">${escapeHtml(r.table_name||'')} • registro ${r.record_id??'—'}</div></div><span class="small muted">${escapeHtml(String(r.created_at||'').replace('T',' '))}</span></div></div>`).join('')||'<div class="empty">Nenhum histórico recebido do PC.</div>'}</div>`}
function bindAuditSearch(){const s=$('#auditSearch');if(s)s.oninput=()=>{setSearchValue('audit',s.value);render()}}
function openAuditDetail(id){const r=(data.desktopExtra.auditLog||[]).find(x=>String(x.id)===String(id));if(!r)return;openModal(`<div class="sheet-handle"></div><div class="sheet-title">Detalhe da alteração</div>${infoRows([['Módulo',escapeHtml(r.table_name||'')],['Registro',escapeHtml(String(r.record_id??''))],['Ação',escapeHtml(r.action||'')],['Data/hora',escapeHtml(String(r.created_at||'').replace('T',' '))]])}<label>Antes</label><pre class="code-block">${escapeHtml(prettyJson(r.old_data))}</pre><label>Depois</label><pre class="code-block">${escapeHtml(prettyJson(r.new_data))}</pre><div class="sheet-footer"><button class="primary" onclick="closeModal()">Fechar</button></div>`)}
function prettyJson(v){try{const o=typeof v==='string'?JSON.parse(v):v;return JSON.stringify(o,null,2)}catch{return String(v||'—')}}
function trashPage(){const rows=(data.desktopExtra.trash||[]).slice(0,250);return `${sectionHead('Lixeira','')}<div class="card"><div class="muted small">Registros excluídos no PC. A restauração solicitada pelo celular é processada de forma segura pelo desktop na próxima sincronização.</div>${rows.map(r=>`<div class="entity-card"><div class="row-between"><div><div class="goal-name">${escapeHtml(r.entity_type||'Registro')}</div><div class="tx-sub">ID original ${r.record_id??'—'} • ${escapeHtml(String(r.deleted_at||'').replace('T',' '))}</div></div><button class="secondary compact" onclick="requestTrashRestore('${r.id}')">Restaurar</button></div></div>`).join('')||'<div class="empty">Lixeira vazia ou ainda não sincronizada.</div>'}</div>`}
function requestTrashRestore(id){const r=(data.desktopExtra.trash||[]).find(x=>String(x.id)===String(id));if(!r||!confirm('Solicitar restauração deste registro no PC?'))return;data.desktopExtra.restoreTrashRequests??=[];if(!data.desktopExtra.restoreTrashRequests.some(x=>String(x.trashId)===String(id)))data.desktopExtra.restoreTrashRequests.push({id:uid(),trashId:Number(id),requestedAt:nowIso()});queueChange('trash_restore_request',`Restauração solicitada: ${r.entity_type} #${r.record_id}`);showToast('Solicitação enviada para a próxima sincronização');render()}
function diagnosticsPage(){const d=data.desktopExtra.diagnostics||{},counts=d.counts||{},localCounts={Movimentações:(data.transactions||[]).length,Contas:(data.accounts||[]).length,Dívidas:(data.debts||[]).length,Investimentos:(data.investments||[]).length,Metas:(data.goals||[]).length,Cartões:(data.cards||[]).length};return `${sectionHead('Diagnóstico','')}<div class="kpi-grid-2">${kpiHtml('Integridade do PC',escapeHtml(d.integrity||'Ainda não recebido'),`Gerado ${escapeHtml(String(d.generatedAt||'—').replace('T',' '))}`,String(d.integrity).toLowerCase()==='ok'?'green':'')}${kpiHtml('Chaves estrangeiras',String(d.foreignKeyErrors??'—'),'Erros reportados pelo SQLite',Number(d.foreignKeyErrors||0)?'red':'green')}${kpiHtml('Identificadores duplicados',String(d.duplicateIdentifiers??'—'),'Transações no PC',Number(d.duplicateIdentifiers||0)?'red':'green')}${kpiHtml('Revisão Drive',String(state.meta.driveLastRevision||0),`${state.meta.pendingChanges||0} alteração(ões) local(is)`,'')}</div><div class="card">${appCardTitle('Contagens no celular')}${infoRows(Object.entries(localCounts).map(([k,v])=>[k,String(v)]))}</div><div class="card">${appCardTitle('Contagens informadas pelo PC')}${infoRows(Object.entries(counts).map(([k,v])=>[k,String(v)]))}</div><div class="card">${appCardTitle('Sincronização')}${infoRows([['Conectado',state.meta.syncConnected?'Sim':'Não'],['Automática',state.meta.autoSyncEnabled!==false?'Ativa':'Desligada'],['Intervalo',`${state.meta.autoSyncIntervalSec||60} s`],['Última sincronização',state.meta.lastSyncAt?new Date(state.meta.lastSyncAt).toLocaleString('pt-BR'):'Nunca'],['Último erro',escapeHtml(state.meta.autoSyncLastError||'Nenhum')]])}<button class="secondary full-btn" onclick="nav('sync')">Abrir Central do Drive</button></div>`}

// ---------------- CONFIGURAÇÕES & BACKUP ----------------
function settings(){const ds=data.desktopExtra.desktopSettings||{};return `${sectionHead('Configurações & backup','')}<div class="card form-card"><div class="section-title">Parâmetros financeiros</div><label>Nome do perfil</label><input id="setName" class="field" value="${escapeHtml(data.settings.userName||'Usuário')}"/><label>Renda mensal atual</label><input id="setIncome" class="field" inputmode="decimal" value="${data.settings.monthlyIncome||0}"/><label>Meta de aporte mensal</label><input id="setInvestmentGoal" class="field" inputmode="decimal" value="${data.settings.monthlyInvestmentGoal||0}"/><label>Meses de reserva</label><input id="setReserveMonths" class="field" inputmode="numeric" value="${data.reserve.months||6}"/><label>Backups mantidos</label><input id="setRetention" class="field" inputmode="numeric" value="${data.settings.backupRetention||12}"/><label>Salvar rascunhos automaticamente</label><select id="setAutosave" class="field"><option value="1" ${data.settings.autosave!==false?'selected':''}>Sim</option><option value="0" ${data.settings.autosave===false?'selected':''}>Não</option></select><button class="primary" onclick="saveSettings()">Salvar parâmetros</button></div><div class="card form-card"><div class="section-title">Google Drive</div><div class="muted small">O Client ID é público por natureza no navegador; nunca coloque o client_secret no mobile.</div><label>Google Web Client ID</label><input id="setGoogleClientId" class="field" value="${escapeHtml(state.meta.googleClientId||'')}" placeholder="...apps.googleusercontent.com"/><label>Sincronização automática</label><select id="setAutoSync" class="field"><option value="on" ${state.meta.autoSyncEnabled!==false?'selected':''}>Ativada</option><option value="off" ${state.meta.autoSyncEnabled===false?'selected':''}>Desativada</option></select><label>Verificar a cada</label><select id="setAutoSyncInterval" class="field">${[30,60,120,300].map(x=>`<option value="${x}" ${Number(state.meta.autoSyncIntervalSec||60)===x?'selected':''}>${x<60?`${x} segundos`:x===60?'1 minuto':`${x/60} minutos`}</option>`).join('')}</select><div class="actions-row"><button class="secondary" onclick="saveGoogleClientId()">Salvar Client ID</button><button class="primary" onclick="saveDriveAutoSettings()">Salvar sincronização</button></div></div><div class="card"><div class="section-title">Backup e restauração do celular</div><div class="muted small">O backup JSON é local ao navegador e não substitui os backups SQLite do PC.</div><div class="action-list"><button class="secondary" onclick="exportSyncPackage()">Exportar backup JSON completo</button><button class="secondary" onclick="triggerImport()">Importar backup JSON</button><button class="secondary" onclick="checkPwaUpdate()">Verificar atualização da PWA</button></div></div><div class="card">${appCardTitle('Retenção configurada no PC')}${infoRows([['Backups mantidos',escapeHtml(String(ds.backupRetention??data.settings.backupRetention??'—'))],['Diários',escapeHtml(String(ds.backupDailyKeep??'—'))],['Semanais',escapeHtml(String(ds.backupWeeklyKeep??'—'))],['Mensais',escapeHtml(String(ds.backupMonthlyKeep??'—'))],['Autosave desktop',String(ds.autosaveEnabled??'1')==='1'?'Ativo':'Desligado']])}</div><div class="card"><div class="section-title">Administração</div><div class="menu-card">${adminMenuRows()}</div></div><div class="card"><div class="section-title danger">Zona de segurança</div><button class="secondary danger full-btn" onclick="resetDemoData()">Limpar somente dados locais deste aparelho</button></div>`}
function saveSettings(){data.settings.userName=$('#setName').value.trim()||'Usuário';data.settings.monthlyIncome=Math.max(0,num($('#setIncome').value));data.settings.monthlyInvestmentGoal=Math.max(0,num($('#setInvestmentGoal').value));data.reserve.months=clamp(parseInt($('#setReserveMonths').value||6),1,60);data.settings.backupRetention=clamp(parseInt($('#setRetention').value||12),1,200);data.settings.autosave=$('#setAutosave').value==='1';queueChange('settings','Parâmetros financeiros atualizados');showToast('Configurações salvas');render()}
async function checkPwaUpdate(){try{if(!('serviceWorker' in navigator))return showToast('Service Worker indisponível');const reg=await navigator.serviceWorker.getRegistration();if(!reg)return showToast('PWA ainda não registrada');await reg.update();showToast('Verificação concluída. Reabra o app se houver nova versão.')}catch(e){showToast('Falha ao verificar atualização') }}
function adminMenuRows(){return [['◫','Categorias','categories'],['⚙','Regras de classificação','rules'],['◷','Histórico de alterações','audit'],['♻','Lixeira e recuperação','trash'],['✓','Diagnóstico e integridade','diagnostics'],['▲','Google Drive','sync']].map(([i,n,r])=>`<div class="menu-row" onclick="nav('${r}')"><div class="menu-icon">${i}</div><div>${n}</div><div class="chev">›</div></div>`).join('')}

// ---------------- MAIS ----------------
function more(){return `${sectionHead('Mais','')}<div class="card profile"><div class="avatar">${userInitials(data.settings.userName||'Usuário')}</div><div><div class="goal-name">${escapeHtml(data.settings.userName||'Usuário')}</div><div class="muted small">Controle Financeiro Mobile v0.7 • paridade completa</div></div></div><div class="card menu-card">${[
['⇄','Movimentações','transactions'],['⇩','Importar Nubank','import'],['◔','Orçamento','budget'],['↻','Contas fixas','recurring'],['−','Dívidas','debts'],['∿','Calculadora','calculator'],['◎','Metas & reserva','goals'],['↗','Investimentos','investments'],['◆','Patrimônio','networth'],['▣','Cartões','cards'],['♥','Saúde financeira','health'],['▥','Relatórios','reports']].map(([i,n,r])=>`<div class="menu-row" onclick="nav('${r}')"><div class="menu-icon">${i}</div><div>${n}</div><div class="chev">›</div></div>`).join('')}</div><div class="card menu-card">${adminMenuRows()}<div class="menu-row" onclick="nav('settings')"><div class="menu-icon">⚙</div><div>Configurações & backup</div><div class="chev">›</div></div></div>`}

// ---------------- RENDERIZAÇÃO v0.7 ----------------
function render(){parityEnsureData();const route=currentRoute;const map={home,transactions,newtx:newTransaction,goals,goaldetail:goalDetail,networth,investments,budget,recurring,debts,cards,calculator,health,reports,import:importPage,settings,sync:syncPage,more,categories:categoriesPage,rules:rulesPage,audit:auditPage,trash:trashPage,diagnostics:diagnosticsPage};try{view.innerHTML=(map[route]||more)()}catch(e){console.error('Falha ao renderizar',route,e);view.innerHTML=`${sectionHead('Erro de interface','')}<div class="card"><div class="section-title">Não foi possível abrir esta tela</div><div class="muted">${escapeHtml(e.message||String(e))}</div><button class="primary" onclick="nav('home')">Voltar ao início</button></div>`}document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===route||(route==='goaldetail'&&b.dataset.route==='goals')||(route==='newtx'&&b.dataset.route==='transactions')||(route==='investments'&&b.dataset.route==='networth')));if(route==='transactions')bindTransactions();if(route==='newtx')bindTypeSeg();if(route==='recurring')bindRecurringSearch();if(route==='debts')bindDebtSearch();if(route==='investments')bindInvestmentSearch();if(route==='goals')bindGoals();if(route==='networth')bindAccountSearch();if(route==='cards')bindCardSearch();if(route==='audit')bindAuditSearch();document.querySelector('.brand-subtitle')&&(document.querySelector('.brand-subtitle').textContent='Mobile v0.7');window.scrollTo({top:0,behavior:'instant'})}

// Renderiza novamente depois de carregar as extensões de paridade.
render();
